window.QBANK = window.QBANK || {};
window.QBANK["sma-ekonomi"] = {
  level: "SMA", subject: "Ekonomi", duration: 900,
  questions: [
    { q: "Kelangkaan (scarcity) dalam ilmu ekonomi terjadi karena ....", options: ["jumlah barang di dunia semakin habis punah", "harga barang selalu naik setiap tahun", "manusia malas bekerja sehingga produksi menjadi sedikit", "alat pemuas kebutuhan jumlahnya terbatas, sedangkan kebutuhan manusia tidak terbatas"], answer: 3, solution: "1. Kelangkaan muncul dari ketimpangan antara kebutuhan manusia yang tidak terbatas dan alat pemuas kebutuhan yang jumlahnya terbatas. 2. Barang yang kebutuhannya besar tetapi jumlahnya terbatas menjadi langka, bukan karena barangnya akan punah. 3. Jadi kelangkaan terjadi karena alat pemuas kebutuhan terbatas sedangkan kebutuhan manusia tidak terbatas." },
    { q: "Berikut ini yang BUKAN merupakan faktor penyebab kelangkaan adalah ....", options: ["pertumbuhan penduduk yang cepat", "keterbatasan sumber daya alam", "bencana alam yang merusak hasil produksi", "kebutuhan manusia yang terbatas jumlahnya"], answer: 3, solution: "1. Faktor penyebab kelangkaan antara lain pertumbuhan penduduk, keterbatasan sumber daya alam, bencana alam, dan perbedaan letak geografis. 2. Kebutuhan manusia justru bersifat tidak terbatas — inilah akar dari kelangkaan, bukan faktor penyebab yang bisa dihilangkan. 3. Jadi yang BUKAN faktor penyebab kelangkaan adalah kebutuhan manusia yang terbatas jumlahnya." },
    { q: "Kebutuhan makan, minum, pakaian, dan tempat tinggal menurut intensitasnya termasuk kebutuhan ....", options: ["primer", "sekunder", "tersier", "jasmani"], answer: 0, solution: "1. Menurut intensitasnya, kebutuhan dibagi menjadi primer, sekunder, dan tersier. 2. Kebutuhan primer adalah kebutuhan pokok yang harus dipenuhi agar manusia dapat bertahan hidup, yaitu sandang, pangan, dan papan. 3. Jadi makan, minum, pakaian, dan tempat tinggal termasuk kebutuhan primer." },
    { q: "Rani memiliki uang Rp200.000. Ia bisa membeli sepatu seharga Rp200.000 atau menabung seluruhnya. Jika Rani memilih membeli sepatu, biaya peluangnya adalah ....", options: ["Rp200.000 berupa tabungan yang dikorbankan", "Rp0 karena ia tidak mengeluarkan biaya tambahan", "harga sepatu ditambah bunga tabungan yang hilang", "Rp400.000 karena kehilangan dua pilihan sekaligus"], answer: 0, solution: "1. Biaya peluang adalah nilai dari alternatif terbaik yang dikorbankan ketika membuat suatu pilihan. 2. Rani memilih membeli sepatu sehingga ia mengorbankan pilihan menabung sebesar Rp200.000. 3. Jadi biaya peluangnya adalah Rp200.000 berupa tabungan yang dikorbankan." },
    { q: "Dimas diterima kerja dengan gaji Rp4.500.000 per bulan, tetapi ia memilih membuka usaha sendiri. Biaya peluang dari keputusan Dimas adalah ....", options: ["modal yang ia keluarkan untuk membuka usaha", "seluruh keuntungan yang diperoleh usahanya", "Rp0 karena ia menjadi bos bagi dirinya sendiri", "Rp4.500.000 per bulan berupa gaji yang dikorbankan"], answer: 3, solution: "1. Biaya peluang diukur dari alternatif terbaik yang tidak dipilih, bukan dari biaya yang dikeluarkan untuk pilihan yang diambil. 2. Dimas mengorbankan kesempatan bergaji Rp4.500.000 per bulan demi membuka usaha. 3. Jadi biaya peluang keputusannya adalah Rp4.500.000 per bulan." },
    { q: "Tujuan utama menyusun skala prioritas kebutuhan adalah ....", options: ["menambah jumlah kebutuhan agar hidup lebih sejahtera", "memenuhi kebutuhan yang paling mendesak terlebih dahulu secara efisien", "menghabiskan seluruh pendapatan agar tidak menumpuk", "menghindari menabung karena nilai uang terus turun"], answer: 1, solution: "1. Skala prioritas adalah urutan kebutuhan dari yang paling mendesak hingga yang bisa ditunda. 2. Tujuannya agar pendapatan yang terbatas dipakai untuk kebutuhan terpenting terlebih dahulu sehingga tidak terjadi pemborosan. 3. Jadi tujuannya adalah memenuhi kebutuhan yang paling mendesak terlebih dahulu secara efisien." },
    { q: "Diketahui fungsi permintaan $Q_d = 100 - 2P$ dan fungsi penawaran $Q_s = 20 + 3P$. Harga dan jumlah keseimbangan pasar adalah ....", options: ["$P = 16$ dan $Q = 60$", "$P = 20$ dan $Q = 60$", "$P = 16$ dan $Q = 68$", "$P = 14$ dan $Q = 72$"], answer: 2, solution: "1. Syarat keseimbangan: $Q_d = Q_s$, sehingga $100 - 2P = 20 + 3P$. 2. Pindahkan sukunya: $100 - 20 = 3P + 2P$, diperoleh $80 = 5P$ sehingga $P = 16$. 3. Substitusi $P = 16$ ke fungsi permintaan: $Q = 100 - 2(16) = 100 - 32 = 68$. Jadi $P = 16$ dan $Q = 68$." },
    { q: "Fungsi permintaan $Q_d = 60 - P$ dan fungsi penawaran $Q_s = 2P - 30$. Titik keseimbangan pasarnya adalah ....", options: ["$P = 30$ dan $Q = 30$", "$P = 45$ dan $Q = 15$", "$P = 20$ dan $Q = 40$", "$P = 30$ dan $Q = 90$"], answer: 0, solution: "1. Syarat keseimbangan $Q_d = Q_s$: $60 - P = 2P - 30$. 2. Pindahkan sukunya: $60 + 30 = 2P + P$, diperoleh $90 = 3P$ sehingga $P = 30$. 3. Substitusi ke fungsi permintaan: $Q = 60 - 30 = 30$ (cek dengan penawaran: $2(30) - 30 = 30$). Jadi $P = 30$ dan $Q = 30$." },
    { q: "Fungsi permintaan $Q_d = 120 - 3P$ dan fungsi penawaran $Q_s = 30 + 2P$. Harga dan jumlah keseimbangannya adalah ....", options: ["$P = 15$ dan $Q = 75$", "$P = 22{,}5$ dan $Q = 52{,}5$", "$P = 30$ dan $Q = 30$", "$P = 18$ dan $Q = 66$"], answer: 3, solution: "1. Syarat keseimbangan $Q_d = Q_s$ berarti $120 - 3P = 30 + 2P$. 2. Pindahkan sukunya: $120 - 30 = 2P + 3P$, diperoleh $90 = 5P$ sehingga $P = 18$. 3. Substitusi: $Q = 120 - 3(18) = 120 - 54 = 66$ (cek: $30 + 2(18) = 66$). Jadi $P = 18$ dan $Q = 66$." },
    { q: "Fungsi permintaan $Q_d = 80 - P$ dan fungsi penawaran $Q_s = P - 20$. Pada harga keseimbangan, jumlah barang yang diperjualbelikan adalah ....", options: ["20 unit", "50 unit", "100 unit", "30 unit"], answer: 3, solution: "1. Syarat keseimbangan $Q_d = Q_s$ berarti $80 - P = P - 20$. 2. Pindahkan sukunya: $80 + 20 = P + P$, diperoleh $100 = 2P$ sehingga $P = 50$. 3. Substitusi: $Q = 80 - 50 = 30$ (cek: $50 - 20 = 30$). Jadi jumlah yang diperjualbelikan adalah 30 unit." },
    { q: "Bunyi hukum permintaan adalah ....", options: ["semakin tinggi harga, semakin banyak barang yang ditawarkan", "semakin rendah harga, semakin banyak jumlah barang yang diminta", "harga dan jumlah barang yang diminta selalu bergerak searah", "jumlah permintaan tidak pernah dipengaruhi oleh harga"], answer: 1, solution: "1. Hukum permintaan menyatakan hubungan terbalik antara harga dan jumlah barang yang diminta, dengan syarat ceteris paribus (faktor lain tetap). 2. Artinya jika harga turun jumlah yang diminta naik, dan jika harga naik jumlah yang diminta turun. 3. Jadi bunyinya: semakin rendah harga, semakin banyak jumlah barang yang diminta." },
    { q: "Berikut ini faktor yang dapat menggeser kurva permintaan ke kanan adalah ....", options: ["pendapatan konsumen meningkat", "harga barang itu sendiri naik", "harga barang substitusi turun", "jumlah penduduk berkurang"], answer: 0, solution: "1. Naiknya harga barang itu sendiri hanya menimbulkan pergerakan di sepanjang kurva, bukan pergeseran kurva. 2. Pergeseran kurva ke kanan berarti permintaan bertambah pada setiap tingkat harga, misalnya karena pendapatan konsumen meningkat. 3. Jadi faktor yang menggeser kurva permintaan ke kanan adalah pendapatan konsumen meningkat." },
    { q: "Jika harga pasar berada DI ATAS harga keseimbangan, yang terjadi di pasar adalah ....", options: ["kekurangan barang (shortage) karena pembeli saling berebut", "pasar langsung mencapai keseimbangan yang baru", "penjual menaikkan harga lagi agar barang cepat laku", "kelebihan penawaran (surplus) karena jumlah yang ditawarkan melebihi yang diminta"], answer: 3, solution: "1. Pada harga di atas keseimbangan, harga terlalu mahal bagi pembeli tetapi menarik bagi penjual. 2. Akibatnya jumlah yang ditawarkan ($Q_s$) melebihi jumlah yang diminta ($Q_d$), keadaan ini disebut kelebihan penawaran atau surplus. 3. Jadi yang terjadi di pasar adalah surplus." },
    { q: "Ciri utama pasar persaingan sempurna adalah ....", options: ["penjual dapat menentukan harga secara sepihak", "produk homogen dan penjual bertindak sebagai price taker", "hanya ada satu penjual yang menguasai pasar", "dibutuhkan modal sangat besar untuk masuk ke pasar"], answer: 1, solution: "1. Pasar persaingan sempurna memiliki sangat banyak penjual dan pembeli sehingga tidak satu pun yang mampu memengaruhi harga. 2. Produknya homogen (sama persis) dan setiap penjual hanya menerima harga yang berlaku di pasar — disebut price taker. 3. Jadi cirinya adalah produk homogen dan penjual bertindak sebagai price taker." },
    { q: "Perusahaan listrik negara (PLN) merupakan contoh pasar ....", options: ["persaingan sempurna", "monopolistik", "oligopoli", "monopoli"], answer: 3, solution: "1. PLN adalah satu-satunya perusahaan yang menjual listrik kepada masyarakat tanpa pesaing. 2. Tidak ada barang substitusi yang dekat dan perusahaan lain sulit masuk karena membutuhkan modal serta izin yang sangat besar. 3. Ciri satu penjual tanpa pesaing ini adalah pasar monopoli." },
    { q: "Ciri pasar monopoli adalah ....", options: ["tidak ada hambatan bagi perusahaan baru untuk masuk", "satu penjual, tidak ada barang substitusi dekat, dan menjadi price maker", "banyak penjual dengan produk yang terdiferensiasi", "penjual dan pembeli sama-sama berjumlah banyak"], answer: 1, solution: "1. Pada pasar monopoli hanya ada satu penjual sehingga tidak ada persaingan harga. 2. Karena tidak ada barang pengganti yang dekat, perusahaan bebas menentukan harga sendiri — disebut price maker. 3. Jadi cirinya: satu penjual, tidak ada barang substitusi dekat, dan menjadi price maker." },
    { q: "Industri semen dan operator seluler di Indonesia umumnya digolongkan ke dalam pasar ....", options: ["persaingan sempurna", "monopoli", "oligopoli", "monopsoni"], answer: 2, solution: "1. Industri semen dan operator seluler hanya dikuasai oleh segelintir perusahaan besar. 2. Pasar yang penjualnya sedikit (tetapi lebih dari satu) disebut oligopoli. 3. Jangan dikacaukan dengan monopsoni, yaitu pasar dengan pembeli tunggal. Jadi keduanya termasuk pasar oligopoli." },
    { q: "Hal yang membedakan pasar monopolistik dari pasar persaingan sempurna adalah ....", options: ["jumlah penjualnya hanya satu", "produknya terdiferensiasi dan penjual giat beriklan", "penjual sama sekali tidak dapat menentukan harga", "tidak ada persaingan di antara para penjual"], answer: 1, solution: "1. Pasar persaingan sempurna menjual produk yang homogen, sedangkan pasar monopolistik menjual produk yang dibeda-bedakan (diferensiasi). 2. Karena produknya berbeda-beda, penjual di pasar monopolistik giat beriklan untuk menonjolkan keunggulan produknya. 3. Jadi pembedanya adalah produk terdiferensiasi dan penjual giat beriklan." },
    { q: "Restoran, salon kecantikan, dan kedai kopi merupakan contoh pasar ....", options: ["monopoli", "oligopoli", "persaingan sempurna", "monopolistik"], answer: 3, solution: "1. Restoran, salon, dan kedai kopi jumlahnya banyak, tetapi masing-masing punya ciri khas seperti rasa, suasana, dan merek. 2. Banyak penjual dengan produk yang terdiferensiasi adalah ciri pasar monopolistik. 3. Jadi ketiganya termasuk contoh pasar monopolistik." },
    { q: "Inflasi adalah ....", options: ["kenaikan harga-harga barang dan jasa secara umum dan terus-menerus", "kenaikan harga satu jenis barang karena panen gagal", "penurunan daya beli akibat gaji yang dipotong perusahaan", "keadaan harga barang yang selalu tetap tidak berubah"], answer: 0, solution: "1. Inflasi bukan sekadar naiknya harga satu jenis barang, melainkan kenaikan harga-harga secara umum. 2. Kenaikan itu harus bersifat terus-menerus dalam jangka waktu tertentu, bukan kenaikan sesaat. 3. Jadi inflasi adalah kenaikan harga-harga barang dan jasa secara umum dan terus-menerus." },
    { q: "Indeks Harga Konsumen (IHK) tahun 2024 sebesar 120 dan tahun 2025 sebesar 126. Laju inflasi tahun 2025 adalah ....", options: ["$4{,}76\\%$", "$6\\%$", "$5\\%$", "$26\\%$"], answer: 2, solution: "1. Rumus laju inflasi: $\\text{Inflasi} = \\frac{IHK_t - IHK_{t-1}}{IHK_{t-1}} \\times 100\\%$. 2. Masukkan angkanya: $\\frac{126 - 120}{120} \\times 100\\% = \\frac{6}{120} \\times 100\\%$. 3. $\\frac{6}{120} \\times 100\\% = 5\\%$. Jadi laju inflasi tahun 2025 adalah $5\\%$." },
    { q: "Inflasi sebesar $150\\%$ per tahun digolongkan sebagai inflasi ....", options: ["ringan", "sedang", "merayap", "hiperinflasi"], answer: 3, solution: "1. Berdasarkan tingkat keparahannya, inflasi ringan di bawah $10\\%$, inflasi sedang $10\\%-30\\%$, dan inflasi berat $30\\%-100\\%$. 2. Inflasi di atas $100\\%$ digolongkan sebagai hiperinflasi. 3. Jadi inflasi $150\\%$ termasuk hiperinflasi." },
    { q: "Kenaikan harga BBM yang mendorong naiknya biaya produksi sehingga harga barang-barang ikut naik disebut inflasi ....", options: ["demand pull inflation", "cost push inflation", "deflasi", "stagflasi"], answer: 1, solution: "1. Cost push inflation adalah inflasi yang didorong oleh naiknya biaya produksi. 2. Kenaikan harga BBM menaikkan ongkos produksi, lalu produsen menaikkan harga jual untuk menutup biaya tersebut. 3. Jadi peristiwa ini disebut cost push inflation." },
    { q: "Kebijakan yang dapat dilakukan Bank Indonesia untuk menekan laju inflasi adalah ....", options: ["menaikkan suku bunga acuan (BI-Rate)", "menurunkan suku bunga acuan", "menambah jumlah uang yang beredar", "menurunkan giro wajib minimum bank"], answer: 0, solution: "1. Untuk menekan inflasi, jumlah uang yang beredar harus dikurangi melalui kebijakan moneter kontraktif. 2. Caranya antara lain menaikkan suku bunga acuan agar masyarakat lebih memilih menabung dan laju kredit melambat. 3. Jadi kebijakan BI yang tepat adalah menaikkan suku bunga acuan (BI-Rate)." },
    { q: "Pihak yang paling dirugikan oleh inflasi adalah ....", options: ["debitur (peminjam uang)", "pemerintah sebagai penarik pajak", "kreditur dan masyarakat berpenghasilan tetap", "pedagang yang menaikkan harga barang"], answer: 2, solution: "1. Inflasi menurunkan nilai riil uang: Rp100.000 tahun ini daya belinya lebih kecil pada tahun depan. 2. Kreditur dan masyarakat berpenghasilan tetap dirugikan karena nilai uang yang mereka terima menyusut, sedangkan debitur justru diuntungkan karena nilai riil utangnya turun. 3. Jadi yang paling dirugikan adalah kreditur dan masyarakat berpenghasilan tetap." },
    { q: "Deflasi adalah ....", options: ["laju inflasi yang menurun", "penurunan harga barang dan jasa secara umum dan terus-menerus", "kenaikan harga yang sangat cepat dan tidak terkendali", "keadaan ekonomi tanpa inflasi sama sekali"], answer: 1, solution: "1. Deflasi adalah kebalikan dari inflasi. 2. Jika inflasi adalah kenaikan harga umum yang terus-menerus, maka deflasi adalah penurunan harga barang dan jasa secara umum dan terus-menerus. 3. Jangan dikacaukan dengan disinflasi yang artinya laju inflasi yang menurun." },
    { q: "Fungsi utama Bank Indonesia sebagai bank sentral adalah ....", options: ["menghimpun dana dari masyarakat dan menyalurkan kredit", "mencetak laba sebesar-besarnya bagi negara", "memberi pinjaman langsung kepada masyarakat umum", "mengatur dan menjaga stabilitas nilai rupiah"], answer: 3, solution: "1. Bank Indonesia adalah bank sentral, bukan bank umum yang mencari laba. 2. Tugas utamanya menurut undang-undang adalah mengatur dan menjaga stabilitas nilai rupiah, baik terhadap harga barang maupun terhadap mata uang asing. 3. Jadi fungsi utamanya adalah mengatur dan menjaga stabilitas nilai rupiah." },
    { q: "Berikut ini tugas Bank Indonesia, KECUALI ....", options: ["menetapkan dan melaksanakan kebijakan moneter", "mengatur dan menjaga kelancaran sistem pembayaran", "menghimpun dana masyarakat dalam bentuk tabungan", "menjaga stabilitas nilai rupiah"], answer: 2, solution: "1. Tugas BI meliputi menetapkan kebijakan moneter, menjaga kelancaran sistem pembayaran, dan menjaga stabilitas nilai rupiah. 2. Menghimpun dana masyarakat dalam bentuk tabungan adalah kegiatan bank umum, bukan bank sentral. 3. Jadi yang BUKAN tugas BI adalah menghimpun dana masyarakat dalam bentuk tabungan." },
    { q: "Lembaga yang bertugas mengawasi industri perbankan, pasar modal, dan lembaga keuangan non-bank di Indonesia adalah ....", options: ["OJK (Otoritas Jasa Keuangan)", "LPS (Lembaga Penjamin Simpanan)", "BPK (Badan Pemeriksa Keuangan)", "KPK (Komisi Pemberantasan Korupsi)"], answer: 0, solution: "1. Sejak tahun 2014, fungsi pengawasan bank dialihkan dari Bank Indonesia ke lembaga baru yang independen. 2. Lembaga tersebut adalah Otoritas Jasa Keuangan (OJK) yang mengawasi perbankan, pasar modal, dan lembaga keuangan non-bank. 3. Jadi jawabannya adalah OJK." },
    { q: "Fungsi LPS (Lembaga Penjamin Simpanan) adalah ....", options: ["mengawasi seluruh bank di Indonesia", "menetapkan suku bunga simpanan bank", "menjamin simpanan nasabah bank hingga batas tertentu", "memberi pinjaman kepada bank yang bangkrut"], answer: 2, solution: "1. LPS dibentuk untuk melindungi dana nasabah apabila bank dilikuidasi atau dicabut izin usahanya. 2. LPS menjamin simpanan nasabah yang memenuhi syarat hingga Rp2 miliar per nasabah per bank. 3. Jadi fungsi LPS adalah menjamin simpanan nasabah bank hingga batas tertentu." },
    { q: "Kegiatan usaha yang TIDAK boleh dilakukan oleh BPR (Bank Perkreditan Rakyat) adalah ....", options: ["menyalurkan kredit kepada UMKM", "menghimpun dana dalam bentuk tabungan", "menghimpun dana dalam bentuk giro dan ikut kliring", "menerima simpanan deposito berjangka"], answer: 2, solution: "1. BPR hanya boleh menghimpun dana dalam bentuk tabungan dan deposito, serta menyalurkan kredit terutama kepada UMKM. 2. BPR dilarang menghimpun dana dalam bentuk giro, ikut serta dalam kliring, dan melakukan kegiatan valuta asing. 3. Jadi yang tidak boleh dilakukan BPR adalah menghimpun dana dalam bentuk giro dan ikut kliring." },
    { q: "Simpanan pada bank yang penarikannya hanya dapat dilakukan dalam jangka waktu tertentu sesuai perjanjian disebut ....", options: ["tabungan", "deposito", "giro", "cek"], answer: 1, solution: "1. Tabungan dapat ditarik sewaktu-waktu, sedangkan giro penarikannya memakai cek atau bilyet giro. 2. Simpanan yang baru dapat ditarik setelah jangka waktu tertentu sesuai perjanjian disebut deposito berjangka. 3. Jadi jawabannya adalah deposito." },
    { q: "APBN ditetapkan setiap tahun dengan ....", options: ["keputusan presiden", "peraturan Bank Indonesia", "undang-undang", "peraturan daerah"], answer: 2, solution: "1. APBN memuat rencana pendapatan dan belanja negara selama satu tahun anggaran. 2. APBN disusun oleh pemerintah dengan persetujuan DPR dan ditetapkan dalam bentuk undang-undang. 3. Jadi APBN ditetapkan setiap tahun dengan undang-undang." },
    { q: "Fungsi APBN yang bertujuan mengurangi kesenjangan pendapatan dan pemerataan pembangunan disebut fungsi ....", options: ["distribusi", "alokasi", "stabilisasi", "otorisasi"], answer: 0, solution: "1. APBN memiliki tiga fungsi utama: alokasi (menyediakan barang publik), distribusi (pemerataan), dan stabilisasi (menjaga kondisi ekonomi). 2. Upaya mengurangi kesenjangan pendapatan, misalnya melalui subsidi dan bantuan sosial, termasuk fungsi distribusi. 3. Jadi jawabannya adalah fungsi distribusi." },
    { q: "Kebijakan fiskal adalah kebijakan pemerintah dalam mengatur ....", options: ["jumlah uang beredar melalui bank sentral", "suku bunga dan nilai tukar rupiah", "penerimaan dan pengeluaran negara (pajak dan belanja negara)", "harga barang-barang di pasar"], answer: 2, solution: "1. Kebijakan fiskal dijalankan oleh pemerintah melalui APBN. 2. Instrumennya adalah penerimaan negara (terutama pajak) dan pengeluaran atau belanja negara. 3. Jangan dikacaukan dengan kebijakan moneter yang mengatur jumlah uang beredar melalui bank sentral." },
    { q: "Untuk mengatasi pengangguran dan lesunya perekonomian, pemerintah sebaiknya menerapkan kebijakan fiskal ....", options: ["kontraktif, yaitu menaikkan pajak dan mengurangi belanja negara", "ekspansif, yaitu menurunkan pajak dan menambah belanja negara", "netral, yaitu tidak mengubah pajak maupun belanja negara", "moneter, yaitu menaikkan suku bunga acuan"], answer: 1, solution: "1. Pengangguran dan ekonomi yang lesu perlu didorong dengan menambah daya beli dan kegiatan ekonomi masyarakat. 2. Caranya adalah menurunkan pajak agar pendapatan masyarakat bertambah dan menambah belanja negara — disebut kebijakan fiskal ekspansif. 3. Jadi pemerintah sebaiknya menerapkan kebijakan fiskal ekspansif." },
    { q: "APBN mengalami defisit apabila ....", options: ["pendapatan negara sama dengan belanja negara", "belanja negara lebih besar daripada pendapatan negara", "pendapatan negara lebih besar daripada belanja negara", "negara tidak memiliki utang sama sekali"], answer: 1, solution: "1. Defisit berarti tekor, yaitu pengeluaran lebih besar daripada pemasukan. 2. Dalam APBN, defisit terjadi ketika belanja negara melebihi pendapatan negara. 3. Kebalikannya, ketika pendapatan melebihi belanja, disebut surplus." },
    { q: "Ciri pajak yang membedakannya dari retribusi adalah ....", options: ["dibayar secara sukarela oleh wajib pajak", "pembayarnya tidak menerima kontraprestasi secara langsung", "hanya dipungut oleh pemerintah daerah", "besarnya selalu sama untuk semua orang"], answer: 1, solution: "1. Pajak dan retribusi sama-sama pungutan wajib, tetapi retribusi memberi imbalan langsung kepada pembayarnya, misalnya retribusi parkir. 2. Pembayar pajak tidak menerima kontraprestasi (imbalan) secara langsung atas pajak yang dibayarnya. 3. Inilah ciri yang membedakan pajak dari retribusi." },
    { q: "Berikut ini yang BUKAN merupakan manfaat perdagangan internasional adalah ....", options: ["memperoleh barang yang tidak dapat diproduksi di dalam negeri", "memperluas pasar hasil produksi dalam negeri", "menambah devisa negara melalui ekspor", "meningkatkan ketergantungan mutlak pada negara lain"], answer: 3, solution: "1. Manfaat perdagangan internasional antara lain memperoleh barang yang tidak diproduksi sendiri, memperluas pasar, dan menambah devisa negara. 2. Ketergantungan mutlak pada negara lain justru merupakan dampak negatif yang harus diwaspadai, bukan manfaat. 3. Jadi yang BUKAN manfaat adalah meningkatkan ketergantungan mutlak pada negara lain." },
    { q: "Apabila nilai tukar rupiah MELEMAH terhadap dolar AS, dampaknya bagi Indonesia adalah ....", options: ["barang impor menjadi lebih murah", "barang ekspor Indonesia menjadi lebih mahal di luar negeri", "barang impor menjadi lebih mahal dan ekspor lebih kompetitif", "harga barang dalam negeri pasti ikut turun"], answer: 2, solution: "1. Rupiah melemah artinya dibutuhkan lebih banyak rupiah untuk membeli satu dolar AS. 2. Akibatnya barang impor menjadi lebih mahal, sedangkan harga barang ekspor Indonesia menjadi lebih murah bagi pembeli luar negeri sehingga lebih kompetitif. 3. Jadi dampaknya: barang impor lebih mahal dan ekspor lebih kompetitif." },
    { q: "Seorang eksportir menerima pembayaran sebesar $\\text{USD } 2.500$. Jika kurs jual $\\text{USD } 1 = \\text{Rp}16.200$, rupiah yang diterima eksportir adalah ....", options: ["$\\text{Rp}40.500.000$", "$\\text{Rp}18.700$", "$\\text{Rp}6.480.000$", "$\\text{Rp}405.000.000$"], answer: 0, solution: "1. Nilai rupiah yang diterima = jumlah dolar dikali kurs jual. 2. $2.500 \\times 16.200 = 40.500.000$. 3. Jadi eksportir menerima Rp40.500.000." },
    { q: "Neraca perdagangan mengalami surplus apabila ....", options: ["impor barang lebih besar daripada ekspor barang", "nilai ekspor barang lebih besar daripada impor barang", "jumlah jasa yang diimpor meningkat tajam", "neraca pembayaran mengalami defisit"], answer: 1, solution: "1. Neraca perdagangan mencatat ekspor dan impor barang suatu negara. 2. Surplus terjadi ketika nilai ekspor barang lebih besar daripada nilai impor barang. 3. Kebalikannya, ketika impor lebih besar daripada ekspor, disebut defisit neraca perdagangan." },
    { q: "Berikut ini yang BUKAN merupakan sumber devisa negara adalah ....", options: ["ekspor barang dan jasa ke luar negeri", "kunjungan wisatawan mancanegara", "impor barang konsumsi dari luar negeri", "jasa tenaga kerja Indonesia di luar negeri"], answer: 2, solution: "1. Devisa adalah valuta asing yang diperoleh negara; sumbernya antara lain ekspor barang dan jasa, wisatawan mancanegara, dan TKI di luar negeri. 2. Impor justru mengeluarkan devisa untuk membayar barang dari luar negeri. 3. Jadi yang BUKAN sumber devisa adalah impor barang konsumsi dari luar negeri." },
    { q: "Praktik menjual barang ke luar negeri dengan harga lebih murah daripada harga di dalam negeri disebut ....", options: ["kuota", "tarif", "subsidi", "dumping"], answer: 3, solution: "1. Dumping adalah strategi menjual barang ke luar negeri dengan harga lebih murah daripada harga di dalam negeri untuk menguasai pasar. 2. Praktik ini dianggap persaingan tidak sehat dan dapat dikenai bea masuk anti-dumping. 3. Jadi jawabannya adalah dumping." },
    { q: "Diketahui total aset perusahaan Rp50.000.000 dan total kewajiban Rp20.000.000. Besar modal perusahaan adalah ....", options: ["Rp70.000.000", "Rp20.000.000", "Rp30.000.000", "Rp10.000.000"], answer: 2, solution: "1. Persamaan dasar akuntansi: $\\text{Aset} = \\text{Kewajiban} + \\text{Modal}$. 2. Maka $\\text{Modal} = \\text{Aset} - \\text{Kewajiban} = 50.000.000 - 20.000.000$. 3. Jadi modal perusahaan adalah Rp30.000.000." },
    { q: "Modal awal Salon Cantik Rp25.000.000. Selama sebulan diperoleh laba Rp8.000.000 dan pemilik mengambil prive Rp2.000.000. Modal akhir salon tersebut adalah ....", options: ["Rp31.000.000", "Rp35.000.000", "Rp33.000.000", "Rp19.000.000"], answer: 0, solution: "1. Rumus modal akhir: $\\text{Modal akhir} = \\text{Modal awal} + \\text{Laba} - \\text{Prive}$. 2. Masukkan angkanya: $25.000.000 + 8.000.000 - 2.000.000 = 31.000.000$. 3. Jadi modal akhir Salon Cantik adalah Rp31.000.000." },
    { q: "Dibayar sewa kantor bulan ini sebesar Rp3.000.000 secara tunai. Jurnal yang benar untuk transaksi tersebut adalah ....", options: ["Kas (D) Rp3.000.000; Beban Sewa (K) Rp3.000.000", "Beban Sewa (D) Rp3.000.000; Kas (K) Rp3.000.000", "Sewa Dibayar di Muka (D) Rp3.000.000; Kas (K) Rp3.000.000", "Kas (D) Rp3.000.000; Modal (K) Rp3.000.000"], answer: 1, solution: "1. Sewa kantor untuk bulan berjalan adalah beban; beban yang bertambah dicatat di debit. 2. Pembayaran tunai membuat kas berkurang; kas yang berkurang dicatat di kredit. 3. Jadi jurnal yang benar: Beban Sewa (D) Rp3.000.000; Kas (K) Rp3.000.000." },
    { q: "Bengkel Maju memperoleh pendapatan jasa Rp15.000.000. Beban-bebannya: gaji Rp5.000.000, sewa Rp2.000.000, dan perlengkapan Rp1.000.000. Laba bersih bengkel tersebut adalah ....", options: ["Rp15.000.000", "Rp10.000.000", "Rp8.000.000", "Rp7.000.000"], answer: 3, solution: "1. Total beban = $5.000.000 + 2.000.000 + 1.000.000 = 8.000.000$. 2. Laba bersih = pendapatan $-$ total beban = $15.000.000 - 8.000.000$. 3. Jadi laba bersih Bengkel Maju adalah Rp7.000.000." },
    { q: "Berikut ini kelompok akun yang semuanya termasuk aset (harta) adalah ....", options: ["kas, piutang usaha, peralatan", "utang usaha, modal, prive", "pendapatan jasa, beban gaji", "kas, utang bank, pendapatan jasa"], answer: 0, solution: "1. Aset adalah harta perusahaan, contohnya kas, piutang usaha, dan peralatan. 2. Utang dan modal termasuk kewajiban dan ekuitas, sedangkan pendapatan dan beban termasuk akun nominal. 3. Jadi kelompok yang semuanya aset adalah kas, piutang usaha, peralatan." },
    { q: "Laporan keuangan yang menyajikan pendapatan, beban, serta laba atau rugi perusahaan selama satu periode disebut ....", options: ["laporan laba rugi", "neraca", "laporan perubahan modal", "jurnal umum"], answer: 0, solution: "1. Laporan laba rugi menyajikan pendapatan dan beban selama satu periode akuntansi. 2. Selisih antara pendapatan dan beban menunjukkan laba bersih atau rugi bersih perusahaan. 3. Neraca menyajikan posisi keuangan pada tanggal tertentu, sedangkan jurnal umum mencatat transaksi harian." },
    { q: "Karena alat pemuas kebutuhan jumlahnya terbatas, manusia harus ...", options: ["memproduksi barang terus-menerus", "membuat pilihan dan skala prioritas", "menimbun barang", "berutang"], answer: 1, solution: "1. Kebutuhan manusia tidak terbatas sedangkan alat pemuasnya terbatas. 2. Manusia tidak mungkin memenuhi semua kebutuhan sekaligus. 3. Oleh karena itu manusia harus membuat pilihan dan menyusun skala prioritas." },
    { q: "Sepeda motor bagi seorang pelajar termasuk kebutuhan ...", options: ["primer", "sekunder", "tersier", "rohani"], answer: 1, solution: "1. Kebutuhan primer adalah kebutuhan pokok untuk bertahan hidup. 2. Sepeda motor bukan kebutuhan pokok, tetapi menunjang kenyamanan dan kelancaran aktivitas. 3. Kebutuhan penunjang kenyamanan hidup termasuk kebutuhan sekunder." },
    { q: "Kebutuhan primer, sekunder, dan tersier merupakan penggolongan kebutuhan menurut ...", options: ["intensitasnya", "waktunya", "sifatnya", "subjeknya"], answer: 0, solution: "1. Kebutuhan primer lebih mendesak daripada sekunder, dan sekunder lebih mendesak daripada tersier. 2. Penggolongan ini didasarkan pada tingkat kepentingan atau kemendesakan. 3. Jadi penggolongan tersebut menurut intensitasnya." },
    { q: "Berdasarkan wujudnya, alat pemuas kebutuhan dibedakan menjadi ...", options: ["benda dan jasa", "primer dan sekunder", "individu dan kolektif", "ekonomi dan nonekonomi"], answer: 0, solution: "1. Ada alat pemuas yang berwujud fisik dan dapat diraba. 2. Ada pula yang tidak berwujud, berupa pelayanan atau keterampilan. 3. Berdasarkan wujudnya, alat pemuas kebutuhan dibedakan menjadi benda dan jasa." },
    { q: "Biaya peluang (opportunity cost) adalah ...", options: ["biaya produksi", "nilai kesempatan terbaik yang dikorbankan", "biaya tetap", "biaya variabel"], answer: 1, solution: "1. Setiap pilihan berarti mengorbankan pilihan lain yang tidak diambil. 2. Pengorbanan terbesar adalah kesempatan terbaik yang dilepaskan. 3. Nilai kesempatan terbaik yang dikorbankan ini disebut biaya peluang." },
    { q: "Seorang petani memilih menanam padi daripada jagung. Biaya peluangnya adalah ...", options: ["biaya bibit padi", "keuntungan menanam jagung yang dikorbankan", "harga jual padi", "upah buruh tani"], answer: 1, solution: "1. Petani hanya dapat memilih satu dari dua alternatif. 2. Dengan memilih padi, ia kehilangan kesempatan memperoleh hasil dari jagung. 3. Jadi biaya peluangnya adalah keuntungan menanam jagung yang dikorbankan." },
    { q: "Bunyi prinsip ekonomi adalah ...", options: ["pengorbanan sekecil-kecilnya untuk hasil sebesar-besarnya", "hasil sekecil-kecilnya dengan pengorbanan sebesar-besarnya", "menghalalkan segala cara", "menimbun barang sebanyak-banyaknya"], answer: 0, solution: "1. Sumber daya terbatas menuntut manusia bertindak efisien. 2. Efisien berarti meminimalkan pengorbanan dan memaksimalkan hasil. 3. Jadi prinsip ekonomi adalah pengorbanan sekecil-kecilnya untuk hasil sebesar-besarnya." },
    { q: "Motif ekonomi adalah ...", options: ["dorongan untuk melakukan tindakan ekonomi", "keinginan untuk pamer", "rasa takut miskin", "sikap ikut-ikutan"], answer: 0, solution: "1. Manusia bekerja, berdagang, dan menabung karena ada yang mendorongnya. 2. Dorongan batin untuk memenuhi kebutuhan dan memperoleh keuntungan inilah penggeraknya. 3. Dorongan untuk melakukan tindakan ekonomi disebut motif ekonomi." },
    { q: "Tindakan ekonomi yang rasional adalah tindakan yang ...", options: ["mempertimbangkan untung rugi sebelum bertindak", "selalu membeli barang mahal", "menuruti gengsi", "berbelanja secara impulsif"], answer: 0, solution: "1. Tindakan rasional berarti didasarkan pada pertimbangan akal sehat. 2. Pelaku ekonomi yang rasional menghitung manfaat dan biaya pilihannya. 3. Jadi tindakan ekonomi rasional adalah yang mempertimbangkan untung rugi sebelum bertindak." },
    { q: "Kegiatan beribadah termasuk kebutuhan ...", options: ["jasmani", "rohani", "primer", "sekunder"], answer: 1, solution: "1. Kebutuhan jasmani berkaitan dengan fisik seperti makan dan pakaian. 2. Beribadah memenuhi ketenangan batin, bukan kebutuhan fisik. 3. Kebutuhan yang bersifat batiniah seperti beribadah termasuk kebutuhan rohani." },
    { q: "Jalan raya, jembatan, dan taman kota termasuk kebutuhan ...", options: ["individu", "kolektif", "primer jasmani", "mewah"], answer: 1, solution: "1. Kebutuhan individu hanya dirasakan perorangan. 2. Jalan raya dan taman kota dimanfaatkan bersama oleh masyarakat. 3. Kebutuhan yang dirasakan bersama masyarakat disebut kebutuhan kolektif." },
    { q: "Kelangkaan sumber daya alam terjadi karena sumber daya alam ...", options: ["jumlahnya terbatas dan sulit diperbarui", "harganya murah", "mudah didapat", "tidak berguna"], answer: 0, solution: "1. Sumber daya seperti minyak bumi dan batu bara terbentuk jutaan tahun. 2. Pengambilannya jauh lebih cepat daripada pembentukannya. 3. Jadi kelangkaan SDA karena jumlahnya terbatas dan sulit diperbarui." },
    { q: "Cara tepat mengatasi kelangkaan adalah ...", options: ["menghemat pemakaian dan mencari barang pengganti", "menimbun barang", "menaikkan harga", "mengurangi penduduk"], answer: 0, solution: "1. Kelangkaan tidak dapat dihilangkan, hanya dapat disiasati. 2. Manusia dapat memakai sumber daya secara hemat dan mencari substitusi. 3. Jadi cara tepatnya adalah menghemat pemakaian dan mencari barang pengganti." },
    { q: "Kegiatan menabung termasuk upaya memenuhi kebutuhan ...", options: ["kebutuhan sekarang", "kebutuhan masa datang", "kebutuhan primer", "kebutuhan rohani"], answer: 1, solution: "1. Menabung berarti menyisihkan uang untuk tidak dipakai saat ini. 2. Uang yang disisihkan disiapkan untuk keperluan di kemudian hari. 3. Jadi menabung termasuk memenuhi kebutuhan masa datang." },
    { q: "Menurut Adam Smith, ilmu ekonomi adalah ilmu yang mempelajari ...", options: ["kekayaan negara dan sebab-sebabnya", "perilaku konsumen saja", "uang dan bank", "perdagangan internasional"], answer: 0, solution: "1. Adam Smith menulis buku The Wealth of Nations (1776). 2. Buku tersebut membahas penyelidikan tentang sifat dan sebab kekayaan negara. 3. Jadi menurut Adam Smith ilmu ekonomi mempelajari kekayaan negara dan sebab-sebabnya." },
    { q: "Inti dari ilmu ekonomi adalah mempelajari ...", options: ["cara manusia memenuhi kebutuhan yang tak terbatas dengan sumber daya terbatas", "cara menjadi kaya raya", "cara menabung di bank", "cara berdagang"], answer: 0, solution: "1. Masalah pokok ekonomi adalah ketimpangan kebutuhan dan sumber daya. 2. Ilmu ekonomi mencari cara terbaik mengalokasikan sumber daya yang langka. 3. Jadi intinya mempelajari cara memenuhi kebutuhan tak terbatas dengan sumber daya terbatas." },
    { q: "Bunyi hukum penawaran adalah ...", options: ["harga naik, jumlah yang ditawarkan bertambah", "harga naik, jumlah yang diminta berkurang", "harga turun, jumlah yang ditawarkan bertambah", "harga tetap, jumlah tetap"], answer: 0, solution: "1. Hukum penawaran menjelaskan hubungan harga dan jumlah yang ditawarkan. 2. Saat harga naik, produsen terdorong memproduksi lebih banyak karena untung lebih besar. 3. Jadi bunyinya: harga naik, jumlah yang ditawarkan bertambah (ceteris paribus)." },
    { q: "Berikut ini yang memengaruhi permintaan, KECUALI ...", options: ["harga barang itu sendiri", "pendapatan konsumen", "selera konsumen", "biaya produksi"], answer: 3, solution: "1. Permintaan dipengaruhi harga barang, pendapatan, selera, dan jumlah penduduk. 2. Biaya produksi memengaruhi keputusan produsen, bukan konsumen. 3. Jadi yang tidak memengaruhi permintaan adalah biaya produksi." },
    { q: "Kurva permintaan bergerak dari ...", options: ["kiri atas ke kanan bawah", "kiri bawah ke kanan atas", "horizontal", "vertikal"], answer: 0, solution: "1. Sumbu horizontal menunjukkan jumlah, sumbu vertikal menunjukkan harga. 2. Saat harga tinggi jumlah yang diminta sedikit, saat harga rendah jumlah banyak. 3. Jadi kurva permintaan menurun dari kiri atas ke kanan bawah." },
    { q: "Permintaan efektif adalah permintaan yang ...", options: ["berupa keinginan tanpa daya beli", "didukung oleh daya beli", "dilakukan produsen", "bersifat kebutuhan pokok"], answer: 1, solution: "1. Keinginan saja belum tentu berwujud pembelian. 2. Permintaan baru berpengaruh di pasar jika konsumen mampu membayar. 3. Permintaan yang didukung daya beli disebut permintaan efektif." },
    { q: "Kurva penawaran bergerak dari ...", options: ["kiri atas ke kanan bawah", "kiri bawah ke kanan atas", "horizontal", "vertikal"], answer: 1, solution: "1. Sumbu horizontal menunjukkan jumlah, sumbu vertikal menunjukkan harga. 2. Saat harga rendah jumlah yang ditawarkan sedikit, saat harga tinggi jumlah banyak. 3. Jadi kurva penawaran menaik dari kiri bawah ke kanan atas." },
    { q: "Harga keseimbangan (equilibrium) terjadi pada saat ...", options: ["jumlah yang diminta sama dengan jumlah yang ditawarkan", "harga mencapai titik tertinggi", "harga mencapai titik terendah", "laba produsen maksimum"], answer: 0, solution: "1. Jika jumlah diminta melebihi ditawarkan terjadi kekurangan barang. 2. Jika jumlah ditawarkan melebihi diminta terjadi kelebihan barang. 3. Keseimbangan tercapai saat jumlah yang diminta sama dengan jumlah yang ditawarkan." },
    { q: "Fungsi permintaan Qd = 80 - 2P. Pada harga P = 15, jumlah yang diminta sebesar ...", options: ["50", "65", "110", "30"], answer: 0, solution: "1. Masukkan P = 15 ke fungsi permintaan: Qd = 80 - 2(15). 2. Hitung: 80 - 30 = 50. 3. Jadi jumlah yang diminta sebesar 50 unit." },
    { q: "Fungsi penawaran Qs = 3P - 30. Pada harga P = 25, jumlah yang ditawarkan sebesar ...", options: ["45", "105", "15", "75"], answer: 0, solution: "1. Masukkan P = 25 ke fungsi penawaran: Qs = 3(25) - 30. 2. Hitung: 75 - 30 = 45. 3. Jadi jumlah yang ditawarkan sebesar 45 unit." },
    { q: "Diketahui Qd = 90 - 3P dan Qs = 2P - 10. Harga dan jumlah keseimbangannya adalah ...", options: ["P = 20, Q = 30", "P = 30, Q = 20", "P = 18, Q = 36", "P = 25, Q = 15"], answer: 0, solution: "1. Syarat keseimbangan: Qd = Qs, sehingga 90 - 3P = 2P - 10. 2. Pindahkan: 90 + 10 = 5P, diperoleh P = 20. 3. Masukkan ke Qd: 90 - 3(20) = 30, jadi P = 20 dan Q = 30." },
    { q: "Pada harga Rp10.000 jumlah yang diminta 100 unit dan jumlah yang ditawarkan 150 unit. Kondisi pasar adalah ...", options: ["surplus 50 unit", "shortage 50 unit", "seimbang", "surplus 250 unit"], answer: 0, solution: "1. Jumlah yang ditawarkan (150) lebih besar daripada yang diminta (100). 2. Selisihnya 150 - 100 = 50 unit berlebih. 3. Kelebihan penawaran ini disebut surplus 50 unit." },
    { q: "Jika harga pasar berada DI BAWAH harga keseimbangan, yang terjadi di pasar adalah ...", options: ["kelebihan penawaran", "kekurangan barang (shortage)", "pasar seimbang", "produsen untung besar"], answer: 1, solution: "1. Harga murah membuat banyak konsumen ingin membeli. 2. Namun produsen enggan memproduksi banyak karena untung kecil. 3. Jumlah diminta melebihi ditawarkan sehingga terjadi kekurangan barang (shortage)." },
    { q: "Kurva permintaan akan bergeser ke kanan apabila ...", options: ["harga barang naik", "pendapatan konsumen naik", "harga barang turun", "jumlah konsumen tetap"], answer: 1, solution: "1. Pergeseran kurva disebabkan faktor selain harga barang itu sendiri. 2. Pendapatan naik membuat daya beli bertambah pada setiap tingkat harga. 3. Jadi kurva permintaan bergeser ke kanan jika pendapatan konsumen naik." },
    { q: "Harga kopi turun menyebabkan kurva permintaan teh bergeser ke kiri karena ...", options: ["teh dan kopi barang substitusi", "teh dan kopi barang komplementer", "teh barang inferior", "kopi barang mewah"], answer: 0, solution: "1. Teh dan kopi dapat saling menggantikan sebagai minuman. 2. Saat kopi murah, konsumen beralih dari teh ke kopi. 3. Karena teh dan kopi barang substitusi, permintaan teh turun (bergeser kiri)." },
    { q: "Kurva penawaran akan bergeser ke kiri apabila ...", options: ["biaya produksi naik", "teknologi membaik", "pajak turun", "jumlah produsen bertambah"], answer: 0, solution: "1. Pergeseran penawaran disebabkan faktor selain harga. 2. Biaya produksi naik membuat produsen mengurangi produksi pada setiap tingkat harga. 3. Jadi kurva penawaran bergeser ke kiri jika biaya produksi naik." },
    { q: "Kenaikan harga kopi menyebabkan permintaan teh ...", options: ["naik karena barang substitusi", "turun karena barang substitusi", "naik karena barang komplementer", "tetap"], answer: 0, solution: "1. Kopi dan teh adalah barang substitusi (saling mengganti). 2. Kopi mahal membuat konsumen beralih ke teh yang relatif murah. 3. Jadi permintaan teh naik karena barang substitusi." },
    { q: "Kenaikan harga bensin menyebabkan permintaan mobil ...", options: ["naik", "turun karena barang komplementer", "tetap", "naik dua kali lipat"], answer: 1, solution: "1. Mobil dan bensin dipakai bersamaan (komplementer). 2. Bensin mahal membuat biaya operasional mobil tinggi. 3. Jadi permintaan mobil turun karena barang komplementer." },
    { q: "Istilah ceteris paribus artinya ...", options: ["semua faktor berubah", "faktor lain dianggap tetap", "harga selalu naik", "permintaan tetap"], answer: 1, solution: "1. Hukum permintaan dan penawaran berlaku dengan syarat tertentu. 2. Syaratnya adalah faktor selain harga tidak berubah. 3. Asumsi faktor lain tetap ini disebut ceteris paribus." },
    { q: "Jika pendapatan konsumen naik, permintaan barang normal akan ...", options: ["naik", "turun", "tetap", "hilang"], answer: 0, solution: "1. Barang normal adalah barang yang permintaannya searah dengan pendapatan. 2. Pendapatan naik berarti daya beli bertambah. 3. Jadi permintaan barang normal akan naik." },
    { q: "Untuk barang inferior, jika pendapatan konsumen naik maka jumlah yang diminta akan ...", options: ["naik", "turun", "tetap", "menjadi nol"], answer: 1, solution: "1. Barang inferior adalah barang bermutu rendah yang dibeli karena murah. 2. Saat pendapatan naik, konsumen beralih ke barang yang lebih baik. 3. Jadi jumlah yang diminta barang inferior akan turun." },
    { q: "Titik keseimbangan pasar pada grafik ditunjukkan oleh ...", options: ["perpotongan kurva permintaan dan penawaran", "titik tertinggi kurva", "titik terendah kurva", "sumbu harga"], answer: 0, solution: "1. Kurva permintaan dan penawaran digambar dalam satu grafik. 2. Pada titik potongnya, harga dan jumlah yang diminta sama dengan yang ditawarkan. 3. Jadi titik keseimbangan adalah perpotongan kedua kurva." },
    { q: "Saat harga turun (ceteris paribus), jumlah yang diminta ...", options: ["bertambah (pergerakan di sepanjang kurva)", "menyebabkan kurva bergeser kiri", "menyebabkan kurva bergeser kanan", "menyebabkan penawaran berkurang"], answer: 0, solution: "1. Perubahan harga barang itu sendiri tidak menggeser kurva. 2. Yang terjadi adalah perpindahan titik di sepanjang kurva yang sama. 3. Harga turun membuat jumlah yang diminta bertambah (pergerakan di sepanjang kurva)." },
    { q: "Kenaikan harga barang X menyebabkan penurunan permintaan barang Y. Maka X dan Y merupakan barang ...", options: ["substitusi", "komplementer", "inferior", "mewah"], answer: 1, solution: "1. Jika X dan Y substitusi, kenaikan harga X justru menaikkan permintaan Y. 2. Di sini permintaan Y ikut turun, berarti Y dipakai bersama X. 3. Jadi X dan Y adalah barang komplementer." },
    { q: "Berikut ini faktor yang memengaruhi penawaran, KECUALI ...", options: ["biaya produksi", "teknologi", "selera konsumen", "pajak"], answer: 2, solution: "1. Penawaran dipengaruhi biaya produksi, teknologi, pajak, dan jumlah produsen. 2. Selera konsumen memengaruhi sisi permintaan, bukan penawaran. 3. Jadi yang bukan faktor penawaran adalah selera konsumen." },
    { q: "Permintaan pasar diperoleh dari ...", options: ["penjumlahan seluruh permintaan individu", "permintaan satu orang", "penawaran produsen", "harga rata-rata"], answer: 0, solution: "1. Setiap konsumen memiliki kurva permintaan individu. 2. Permintaan total di pasar adalah gabungan semua konsumen. 3. Jadi permintaan pasar adalah penjumlahan seluruh permintaan individu." },
    { q: "Barang yang permintaannya naik saat pendapatan konsumen naik disebut barang ...", options: ["normal", "inferior", "substitusi", "komplementer"], answer: 0, solution: "1. Ada barang yang makin laris saat konsumen makin kaya. 2. Hubungan searah antara pendapatan dan permintaan ini adalah ciri khasnya. 3. Barang tersebut disebut barang normal." },
    { q: "Pergeseran kurva penawaran ke kanan artinya ...", options: ["jumlah yang ditawarkan bertambah pada setiap tingkat harga", "harga barang naik", "jumlah yang diminta berkurang", "pasar kekurangan barang"], answer: 0, solution: "1. Kurva bergeser kanan berarti pada harga yang sama jumlahnya lebih banyak. 2. Ini terjadi misalnya karena teknologi membaik atau biaya turun. 3. Jadi artinya jumlah yang ditawarkan bertambah pada setiap tingkat harga." },
    { q: "Pada saat harga keseimbangan tercapai, kondisi pasar adalah ...", options: ["mengalami kliring (tidak ada surplus maupun shortage)", "terjadi antrean pembeli", "barang menumpuk di gudang", "produsen merugi"], answer: 0, solution: "1. Harga keseimbangan menyamakan jumlah diminta dan ditawarkan. 2. Tidak ada kelebihan barang maupun kekurangan barang. 3. Keadaan pasar yang bersih dari surplus dan shortage disebut kliring." },
    { q: "Elastisitas permintaan mengukur ...", options: ["kepekaan jumlah yang diminta terhadap perubahan harga", "jumlah barang yang ditawarkan", "titik keseimbangan pasar", "laju inflasi"], answer: 0, solution: "1. Setiap barang bereaksi berbeda terhadap perubahan harga. 2. Ukuran kepekaan reaksi jumlah yang diminta inilah yang dicari. 3. Jadi elastisitas permintaan mengukur kepekaan jumlah yang diminta terhadap perubahan harga." },
    { q: "Rumus koefisien elastisitas permintaan adalah ...", options: ["persentase perubahan jumlah : persentase perubahan harga", "persentase perubahan harga : persentase perubahan jumlah", "harga dikali jumlah", "perubahan harga ditambah perubahan jumlah"], answer: 0, solution: "1. Elastisitas membandingkan perubahan relatif jumlah dan harga. 2. Perubahan jumlah yang diminta dibagi perubahan harga dalam persen. 3. Jadi rumusnya: persentase perubahan jumlah dibagi persentase perubahan harga." },
    { q: "Harga naik 10% menyebabkan jumlah yang diminta turun 20%. Nilai elastisitas dan sifatnya adalah ...", options: ["2 (elastis)", "0,5 (inelastis)", "1 (uniter)", "0 (inelastis sempurna)"], answer: 0, solution: "1. Hitung Ed = persentase perubahan jumlah : persentase perubahan harga. 2. Ed = 20% : 10% = 2. 3. Karena Ed lebih dari 1, permintaannya bersifat elastis." },
    { q: "Permintaan dengan koefisien elastisitas lebih dari 1 (Ed > 1) disebut ...", options: ["elastis", "inelastis", "uniter", "sempurna"], answer: 0, solution: "1. Nilai Ed membandingkan kepekaan jumlah terhadap harga. 2. Jika perubahan jumlah lebih besar daripada perubahan harga (Ed > 1), permintaannya peka. 3. Permintaan yang peka terhadap harga disebut elastis." },
    { q: "Permintaan dengan koefisien elastisitas kurang dari 1 (Ed < 1) disebut ...", options: ["elastis", "inelastis", "uniter", "sempurna"], answer: 1, solution: "1. Jika perubahan jumlah lebih kecil daripada perubahan harga, permintaannya kurang peka. 2. Nilai Ed di bawah 1 menunjukkan ketidakpekaan tersebut. 3. Permintaan ini disebut inelastis." },
    { q: "Permintaan dengan koefisien elastisitas nol (Ed = 0) disebut ...", options: ["elastis sempurna", "inelastis sempurna", "uniter", "elastis"], answer: 1, solution: "1. Ed = 0 berarti jumlah yang diminta tidak berubah sama sekali. 2. Berapa pun harganya, jumlah yang dibeli tetap. 3. Permintaan yang sama sekali tidak peka ini disebut inelastis sempurna." },
    { q: "Permintaan dengan koefisien elastisitas tak hingga disebut ...", options: ["inelastis sempurna", "elastis sempurna", "uniter", "inelastis"], answer: 1, solution: "1. Pada kondisi ini sedikit saja harga berubah, jumlah yang diminta berubah tak terbatas. 2. Kurvanya horizontal sejajar sumbu jumlah. 3. Permintaan ini disebut elastis sempurna." },
    { q: "Permintaan dengan koefisien elastisitas sama dengan 1 (Ed = 1) disebut ...", options: ["elastis", "inelastis", "uniter (satuan)", "sempurna"], answer: 2, solution: "1. Ed = 1 berarti perubahan jumlah sama persis dengan perubahan harga. 2. Kepekaannya tepat satu banding satu. 3. Permintaan ini disebut elastisitas uniter (satuan)." },
    { q: "Permintaan barang kebutuhan pokok umumnya bersifat ...", options: ["elastis", "inelastis", "uniter", "sempurna"], answer: 1, solution: "1. Beras dan kebutuhan pokok tetap dibeli meski harganya naik. 2. Jumlah yang diminta tidak banyak berubah terhadap perubahan harga. 3. Jadi permintaan barang kebutuhan pokok bersifat inelastis." },
    { q: "Permintaan barang mewah umumnya bersifat ...", options: ["inelastis", "elastis", "uniter", "sempurna"], answer: 1, solution: "1. Barang mewah mudah ditunda atau dibatalkan pembeliannya. 2. Sedikit kenaikan harga membuat jumlah yang diminta turun banyak. 3. Jadi permintaan barang mewah bersifat elastis." },
    { q: "Rumus koefisien elastisitas penawaran adalah ...", options: ["persentase perubahan jumlah ditawarkan : persentase perubahan harga", "persentase perubahan jumlah diminta : persentase perubahan harga", "harga dibagi jumlah", "jumlah dikali harga"], answer: 0, solution: "1. Elastisitas penawaran mengukur kepekaan produsen terhadap harga. 2. Sama seperti permintaan, rumusnya membandingkan perubahan relatif. 3. Jadi rumusnya: persentase perubahan jumlah yang ditawarkan dibagi persentase perubahan harga." },
    { q: "Berikut ini faktor yang memengaruhi elastisitas permintaan, KECUALI ...", options: ["ketersediaan barang substitusi", "proporsi pendapatan untuk barang tersebut", "jangka waktu", "jumlah penduduk"], answer: 3, solution: "1. Elastisitas dipengaruhi substitusi, proporsi pendapatan, dan jangka waktu. 2. Jumlah penduduk memengaruhi besarnya permintaan, bukan kepekaannya terhadap harga. 3. Jadi yang bukan faktor elastisitas adalah jumlah penduduk." },
    { q: "Semakin banyak barang substitusi, permintaan suatu barang semakin ...", options: ["inelastis", "elastis", "uniter", "tetap"], answer: 1, solution: "1. Jika harga naik, konsumen mudah beralih ke barang pengganti. 2. Banyaknya pilihan pengganti membuat konsumen sangat peka terhadap harga. 3. Jadi permintaannya semakin elastis." },
    { q: "Elastisitas silang yang bernilai positif menunjukkan kedua barang merupakan barang ...", options: ["substitusi", "komplementer", "inferior", "normal"], answer: 0, solution: "1. Elastisitas silang mengukur pengaruh harga barang lain. 2. Nilai positif berarti kenaikan harga barang X menaikkan permintaan barang Y. 3. Pola ini terjadi pada barang substitusi (saling mengganti)." },
    { q: "Elastisitas silang yang bernilai negatif menunjukkan kedua barang merupakan barang ...", options: ["substitusi", "komplementer", "mewah", "pokok"], answer: 1, solution: "1. Nilai negatif berarti kenaikan harga barang X menurunkan permintaan barang Y. 2. Keduanya bergerak berlawanan karena dipakai bersamaan. 3. Pola ini terjadi pada barang komplementer." },
    { q: "Elastisitas pendapatan yang bernilai positif menunjukkan barang tersebut adalah barang ...", options: ["normal", "inferior", "bebas", "publik"], answer: 0, solution: "1. Elastisitas pendapatan mengukur pengaruh pendapatan terhadap permintaan. 2. Nilai positif berarti pendapatan naik, permintaan ikut naik. 3. Barang dengan pola ini disebut barang normal." },
    { q: "Pasar konkret dan pasar abstrak merupakan penggolongan pasar menurut ...", options: ["wujudnya", "luasnya", "waktunya", "strukturnya"], answer: 0, solution: "1. Pasar konkret mempertemukan penjual-pembeli secara fisik di satu tempat. 2. Pasar abstrak hanya mempertemukan lewat media tanpa tatap muka. 3. Pembedaan berdasarkan ada-tidaknya wujud fisik ini adalah penggolongan menurut wujudnya." },
    { q: "Pada pasar persaingan sempurna, penjual berperan sebagai ...", options: ["price taker (penerima harga)", "price maker (penentu harga)", "monopolis", "spekulan"], answer: 0, solution: "1. Di pasar persaingan sempurna ada sangat banyak penjual. 2. Penjual individual terlalu kecil untuk memengaruhi harga pasar. 3. Ia hanya menerima harga yang terbentuk pasar, disebut price taker." },
    { q: "Produk yang homogen (tidak ada perbedaan) merupakan ciri pasar ...", options: ["persaingan sempurna", "monopoli", "oligopoli", "monopolistik"], answer: 0, solution: "1. Jika produk semua penjual identik, pembeli hanya peduli harga. 2. Kondisi produk seragam tanpa diferensiasi ini khas suatu struktur pasar. 3. Pasar dengan produk homogen adalah pasar persaingan sempurna." },
    { q: "Contoh pasar yang mendekati persaingan sempurna adalah ...", options: ["pasar beras", "PLN", "operator seluler", "restoran"], answer: 0, solution: "1. Pasar persaingan sempurna butuh banyak penjual dan produk homogen. 2. Beras dari berbagai penjual pada dasarnya sama dan penjualnya banyak. 3. Jadi pasar beras mendekati persaingan sempurna." },
    { q: "PLN menjadi contoh pasar monopoli karena ...", options: ["satu-satunya penjual listrik tanpa substitusi dekat", "banyak penjual listrik", "produknya terdiferensiasi", "harganya bersaing bebas"], answer: 0, solution: "1. Monopoli berarti hanya ada satu penjual di pasar. 2. Listrik PLN tidak memiliki pengganti yang dekat bagi konsumen. 3. Jadi PLN monopoli karena satu-satunya penjual tanpa substitusi dekat." },
    { q: "Hambatan masuk (barrier to entry) pada pasar monopoli bersifat ...", options: ["sangat tinggi sehingga sulit dimasuki pesaing", "sangat rendah", "tidak ada", "hanya butuh modal kecil"], answer: 0, solution: "1. Monopoli bertahan karena pesaing sulit masuk pasar. 2. Hambatannya berupa modal raksasa, aturan pemerintah, atau hak paten. 3. Jadi barrier to entry monopoli sangat tinggi." },
    { q: "Pasar oligopoli adalah pasar dengan ...", options: ["satu penjual", "sedikit penjual yang saling memengaruhi", "banyak penjual", "satu pembeli"], answer: 1, solution: "1. Oligopoli berasal dari kata oligos (sedikit). 2. Keputusan satu perusahaan (misal turun harga) memengaruhi yang lain. 3. Jadi oligopoli adalah pasar dengan sedikit penjual yang saling memengaruhi." },
    { q: "Perang harga (price war) paling mungkin terjadi pada pasar ...", options: ["persaingan sempurna", "oligopoli", "monopoli", "pasar faktor"], answer: 1, solution: "1. Perang harga butuh pesaing yang saling bereaksi. 2. Di oligopoli, jika satu perusahaan menurunkan harga, yang lain ikut. 3. Jadi price war paling mungkin terjadi di pasar oligopoli." },
    { q: "Pasar dengan satu pembeli dan banyak penjual disebut ...", options: ["monopoli", "monopsoni", "oligopoli", "monopolistik"], answer: 1, solution: "1. Monopoli adalah satu penjual, sedangkan pasar ini satu pembeli. 2. Pembeli tunggal memiliki kekuatan menekan harga. 3. Pasar satu pembeli ini disebut monopsoni." },
    { q: "Pasar tenaga kerja termasuk jenis pasar ...", options: ["faktor produksi", "sembako", "modal", "barang"], answer: 0, solution: "1. Tenaga kerja adalah input yang dipakai untuk berproduksi. 2. Pasar tempat jual-beli input produksi disebut pasar faktor produksi. 3. Jadi pasar tenaga kerja termasuk pasar faktor produksi." },
    { q: "Iklan besar-besaran dan diferensiasi produk banyak ditemukan pada pasar ...", options: ["persaingan sempurna", "persaingan monopolistik", "monopoli", "oligopoli"], answer: 1, solution: "1. Jika produk terdiferensiasi, penjual perlu menonjolkan keunikannya. 2. Caranya lewat iklan dan pembeda produk. 3. Pasar dengan banyak penjual dan produk terdiferensiasi adalah persaingan monopolistik." },
    { q: "BEI adalah singkatan dari ...", options: ["Bursa Efek Indonesia", "Bank Ekonomi Indonesia", "Badan Ekonomi Investasi", "Bursa Emas Indonesia"], answer: 0, solution: "1. BEI adalah tempat jual-beli surat berharga di Indonesia. 2. Kata efek berarti surat berharga (saham, obligasi). 3. Jadi BEI adalah Bursa Efek Indonesia." },
    { q: "Saham adalah ...", options: ["bukti kepemilikan perusahaan", "surat utang", "bukti tabungan", "cek"], answer: 0, solution: "1. Perusahaan menjual sebagian kepemilikannya untuk modal. 2. Pembeli mendapat tanda bukti atas bagian kepemilikan tersebut. 3. Tanda bukti kepemilikan perusahaan ini disebut saham." },
    { q: "Obligasi adalah ...", options: ["surat utang", "bukti kepemilikan", "bilyet giro", "cek"], answer: 0, solution: "1. Perusahaan atau negara kadang butuh dana dengan berutang ke publik. 2. Utang tersebut dinyatakan dalam surat berharga berbunga. 3. Surat berharga sebagai tanda utang ini disebut obligasi." },
    { q: "Pasar uang memperjualbelikan surat berharga berjangka waktu ...", options: ["pendek (kurang dari satu tahun)", "panjang", "selamanya", "harian saja"], answer: 0, solution: "1. Pasar uang adalah pasar surat berharga jangka pendek. 2. Instrumennya seperti SBI dan surat berharga komersial jatuh tempo di bawah setahun. 3. Jadi jangka waktunya pendek, kurang dari satu tahun." },
    { q: "Perbedaan utama pasar uang dan pasar modal terletak pada ...", options: ["jangka waktunya", "tempatnya", "pelakunya", "mata uangnya"], answer: 0, solution: "1. Keduanya memperjualbelikan surat berharga. 2. Pasar uang untuk jangka pendek, pasar modal untuk jangka panjang. 3. Jadi perbedaan utamanya adalah jangka waktunya." },
    { q: "Kartel adalah ...", options: ["kerja sama perusahaan oligopoli mengatur harga dan produksi", "penggabungan bank", "pengambilalihan perusahaan", "privatisasi BUMN"], answer: 0, solution: "1. Perusahaan oligopoli kadang bersekongkol daripada bersaing. 2. Mereka sepakat mengatur harga dan membagi produksi. 3. Persekongkolan perusahaan oligopoli ini disebut kartel." },
    { q: "Pasar modal memperjualbelikan ...", options: ["surat berharga jangka panjang", "uang kartal", "barang kebutuhan pokok", "valuta asing"], answer: 0, solution: "1. Pasar modal adalah pasar surat berharga berjangka panjang. 2. Instrumennya antara lain saham dan obligasi. 3. Jadi pasar modal memperjualbelikan surat berharga jangka panjang." },
    { q: "Fungsi utama pasar sebagai tempat bertemunya penjual dan pembeli adalah ...", options: ["pembentukan harga", "mencetak uang", "mengatur pajak", "mengawasi bank"], answer: 0, solution: "1. Di pasar, penjual menawarkan dan pembeli menawar. 2. Interaksi tawar-menawar menghasilkan kesepakatan harga. 3. Jadi fungsi utama pasar adalah pembentukan harga." },
    { q: "Struktur pasar yang paling efisien adalah ...", options: ["persaingan sempurna", "monopoli", "oligopoli", "monopolistik"], answer: 0, solution: "1. Efisiensi berarti sumber daya teralokasi optimal tanpa pemborosan. 2. Pada persaingan sempurna harga sama dengan biaya marjinal dan tidak ada laba berlebih. 3. Jadi struktur pasar paling efisien adalah persaingan sempurna." },
    { q: "Inflasi yang kenaikannya lambat dan kecil (di bawah 10%) disebut inflasi ...", options: ["merayap (creeping)", "sedang", "berat", "hiper"], answer: 0, solution: "1. Inflasi digolongkan menurut lajunya. 2. Kenaikan harga yang perlahan di bawah 10% per tahun disebut inflasi merayap. 3. Inflasi jenis ini masih dianggap wajar dan disebut creeping inflation." },
    { q: "Inflasi ringan terjadi pada kisaran ...", options: ["kurang dari 10%", "10% - 30%", "30% - 100%", "lebih dari 100%"], answer: 0, solution: "1. Penggolongan inflasi didasarkan pada laju kenaikan harga per tahun. 2. Di bawah 10% digolongkan ringan, 10-30% sedang, 30-100% berat. 3. Jadi inflasi ringan kurang dari 10%." },
    { q: "Inflasi sedang terjadi pada kisaran ...", options: ["kurang dari 10%", "10% - 30%", "30% - 100%", "lebih dari 100%"], answer: 1, solution: "1. Inflasi 10-30% mulai mengganggu perekonomian. 2. Kisaran ini disebut inflasi sedang (galloping ringan). 3. Jadi inflasi sedang terjadi pada 10% - 30%." },
    { q: "Inflasi berat terjadi pada kisaran ...", options: ["kurang dari 10%", "10% - 30%", "30% - 100%", "lebih dari 100%"], answer: 2, solution: "1. Inflasi 30-100% sangat merusak daya beli masyarakat. 2. Kisaran ini digolongkan sebagai inflasi berat. 3. Jadi inflasi berat terjadi pada 30% - 100%." },
    { q: "Hiperinflasi terjadi pada kisaran ...", options: ["kurang dari 10%", "10% - 30%", "30% - 100%", "lebih dari 100%"], answer: 3, solution: "1. Hiperinflasi adalah inflasi yang tidak terkendali. 2. Batasnya adalah di atas 100% per tahun. 3. Pada kondisi ini uang hampir tidak berharga." },
    { q: "Inflasi sebesar 45% per tahun digolongkan sebagai inflasi ...", options: ["ringan", "sedang", "berat", "hiper"], answer: 2, solution: "1. Golongan inflasi: ringan <10%, sedang 10-30%, berat 30-100%, hiper >100%. 2. Angka 45% berada pada rentang 30-100%. 3. Jadi inflasi 45% termasuk inflasi berat." },
    { q: "Inflasi karena tarikan permintaan (demand pull inflation) terjadi ketika ...", options: ["permintaan agregat melebihi penawaran", "biaya produksi naik", "jumlah uang beredar berkurang", "pajak dinaikkan"], answer: 0, solution: "1. Demand pull berarti inflasi yang ditarik oleh permintaan. 2. Terjadi saat daya beli masyarakat naik tajam sementara barang terbatas. 3. Jadi penyebabnya permintaan agregat melebihi penawaran." },
    { q: "Dampak deflasi bagi perekonomian adalah ...", options: ["masyarakat menunda belanja sehingga produksi lesu", "harga-harga naik cepat", "pengangguran hilang", "daya beli naik tajam"], answer: 0, solution: "1. Deflasi adalah penurunan harga umum terus-menerus. 2. Konsumen menunggu harga makin murah sehingga menunda belanja. 3. Akibatnya produksi lesu dan pengangguran naik." },
    { q: "Penerima pendapatan tetap (misalnya pensiunan) saat terjadi inflasi akan ...", options: ["daya belinya turun", "menjadi kaya", "utangnya lunas", "gajinya naik secara riil"], answer: 0, solution: "1. Pendapatan tetap tidak naik mengikuti harga. 2. Harga naik berarti uang yang sama mendapat barang lebih sedikit. 3. Jadi daya beli penerima pendapatan tetap turun saat inflasi." },
    { q: "Pihak debitur (pengutang) saat terjadi inflasi akan ...", options: ["nilai riil utangnya menurun", "bunga utangnya naik", "utangnya bertambah", "bangkrut"], answer: 0, solution: "1. Utang dibayar dengan nilai nominal yang disepakati dulu. 2. Saat inflasi, nilai uang turun sehingga utang terasa lebih ringan. 3. Jadi debitur diuntungkan karena nilai riil utangnya menurun." },
    { q: "IHK adalah singkatan dari ...", options: ["Indeks Harga Konsumen", "Indeks Harga Komoditas", "Indikator Hasil Kredit", "Indeks Hutang Kota"], answer: 0, solution: "1. Inflasi diukur dari perubahan harga barang kebutuhan konsumen. 2. Ukurannya dirangkum dalam sebuah indeks. 3. Indeks tersebut adalah Indeks Harga Konsumen (IHK)." },
    { q: "Rumus menghitung laju inflasi adalah ...", options: ["(IHK tahun ini - IHK tahun lalu) : IHK tahun lalu x 100%", "(IHK tahun lalu - IHK tahun ini) : IHK tahun ini x 100%", "IHK tahun ini + IHK tahun lalu", "IHK tahun ini : jumlah barang"], answer: 0, solution: "1. Laju inflasi adalah persentase kenaikan IHK. 2. Kenaikan IHK dibagi IHK awal lalu dikali 100%. 3. Jadi rumusnya (IHK tahun ini - IHK tahun lalu) : IHK tahun lalu x 100%." },
    { q: "IHK tahun lalu 150 dan IHK tahun ini 165. Laju inflasinya adalah ...", options: ["10%", "15%", "5%", "12%"], answer: 0, solution: "1. Kenaikan IHK = 165 - 150 = 15. 2. Laju inflasi = 15 : 150 x 100%. 3. Hasilnya 10%." },
    { q: "Tujuan Bank Indonesia menjual SBI dalam operasi pasar terbuka adalah ...", options: ["mengurangi jumlah uang beredar", "menambah jumlah uang beredar", "menurunkan suku bunga", "menaikkan kurs rupiah"], answer: 0, solution: "1. Menjual SBI berarti BI menarik rupiah dari masyarakat. 2. Rupiah yang beredar berkurang sehingga daya beli tertekan. 3. Tujuannya mengurangi jumlah uang beredar untuk menekan inflasi." },
    { q: "Kebijakan fiskal kontraktif untuk menekan inflasi adalah ...", options: ["mengurangi belanja negara dan menaikkan pajak", "menambah belanja negara", "menurunkan pajak", "menambah utang"], answer: 0, solution: "1. Kontraktif berarti mengerem laju perekonomian. 2. Caranya mengurangi belanja negara dan menaikkan pajak agar daya beli turun. 3. Jadi kebijakan fiskal kontraktif adalah mengurangi belanja negara dan menaikkan pajak." },
    { q: "Inflasi ringan dapat menguntungkan produsen karena ...", options: ["harga jual naik sehingga produsen terdorong menambah produksi", "biaya produksi turun", "upah pekerja turun", "pajak dihapuskan"], answer: 0, solution: "1. Pada inflasi ringan, harga jual naik lebih cepat daripada biaya. 2. Margin keuntungan produsen membesar. 3. Keuntungan yang membesar mendorong produsen menambah produksi." },
    { q: "Stagflasi adalah keadaan ...", options: ["inflasi disertai stagnasi ekonomi dan pengangguran", "deflasi dan pertumbuhan", "inflasi ringan", "hiperinflasi"], answer: 0, solution: "1. Stagflasi gabungan kata stagnasi dan inflasi. 2. Terjadi saat harga naik tetapi ekonomi mandek dan pengangguran tinggi. 3. Jadi stagflasi adalah inflasi disertai stagnasi ekonomi dan pengangguran." },
    { q: "Laju inflasi dihitung berdasarkan ...", options: ["perubahan IHK dari waktu ke waktu", "jumlah uang kartal", "kurs dolar AS", "suku bunga bank"], answer: 0, solution: "1. Inflasi adalah kenaikan harga barang umum. 2. Harga umum diukur dengan Indeks Harga Konsumen. 3. Jadi laju inflasi dihitung dari perubahan IHK dari waktu ke waktu." },
    { q: "Kebijakan moneter adalah kebijakan Bank Indonesia dalam mengatur ...", options: ["jumlah uang beredar", "pajak", "belanja negara", "APBN"], answer: 0, solution: "1. Bank Indonesia adalah otoritas moneter, bukan fiskal. 2. Instrumennya seperti suku bunga acuan dan operasi pasar terbuka mengatur uang. 3. Jadi kebijakan moneter mengatur jumlah uang beredar." },
    { q: "Tugas pokok Bank Indonesia sebagai bank sentral adalah ...", options: ["menjaga stabilitas nilai rupiah", "mengawasi pasar modal", "menjamin simpanan nasabah", "memungut pajak"], answer: 0, solution: "1. Bank sentral bertanggung jawab atas nilai mata uang. 2. Di Indonesia tugas ini diamanatkan kepada Bank Indonesia. 3. Jadi tugas pokok BI adalah menjaga stabilitas nilai rupiah." },
    { q: "Sejak 1 Januari 2014, pengawasan bank di Indonesia dilakukan oleh ...", options: ["Bank Indonesia", "OJK", "LPS", "DPR"], answer: 1, solution: "1. Sebelum 2014 bank diawasi oleh Bank Indonesia. 2. Fungsi pengawasan dialihkan agar BI fokus pada stabilitas moneter. 3. Sejak 1 Januari 2014 pengawasan bank dilakukan OJK." },
    { q: "OJK dibentuk berdasarkan ...", options: ["UU No. 21 Tahun 2011", "UU No. 23 Tahun 1999", "UU No. 10 Tahun 1998", "UUD 1945"], answer: 0, solution: "1. OJK adalah lembaga negara yang dibentuk dengan undang-undang. 2. Undang-undang pembentuknya disahkan tahun 2011. 3. OJK dibentuk berdasarkan UU No. 21 Tahun 2011." },
    { q: "Tugas OJK adalah ...", options: ["mengatur dan mengawasi sektor jasa keuangan", "mencetak uang", "memungut pajak", "menjamin simpanan"], answer: 0, solution: "1. OJK mengawasi perbankan, pasar modal, dan lembaga keuangan nonbank. 2. Tujuannya agar industri jasa keuangan sehat dan melindungi konsumen. 3. Jadi tugas OJK adalah mengatur dan mengawasi sektor jasa keuangan." },
    { q: "Simpanan nasabah yang dijamin oleh LPS adalah simpanan yang ...", options: ["tercatat di bank dan memenuhi syarat penjaminan", "disimpan di bawah bantal", "di semua bank tanpa syarat", "hanya berupa deposito"], answer: 0, solution: "1. LPS menjamin simpanan nasabah bank yang resmi tercatat. 2. Ada syarat seperti bunga tidak melebihi tingkat penjaminan. 3. Jadi yang dijamin adalah simpanan tercatat yang memenuhi syarat penjaminan." },
    { q: "Batas maksimal simpanan yang dijamin LPS adalah ...", options: ["Rp100 juta", "Rp500 juta", "Rp2 miliar", "tanpa batas"], answer: 2, solution: "1. LPS menjamin simpanan nasabah per bank. 2. Nilai penjaminan ditetapkan agar sebagian besar nasabah terlindungi. 3. Batas maksimalnya adalah Rp2 miliar per nasabah per bank." },
    { q: "Tabungan, deposito, dan giro termasuk ...", options: ["produk simpanan bank", "produk kredit bank", "jasa bank", "modal bank"], answer: 0, solution: "1. Ketiganya adalah dana yang dititipkan nasabah ke bank. 2. Dana titipan nasabah disebut simpanan. 3. Jadi tabungan, deposito, dan giro termasuk produk simpanan bank." },
    { q: "Simpanan giro penarikannya dapat dilakukan dengan menggunakan ...", options: ["cek dan bilyet giro", "wesel", "deposito berjangka", "kartu kredit"], answer: 0, solution: "1. Giro adalah simpanan yang penarikannya sewaktu-waktu. 2. Penarikan tidak memakai buku tabungan melainkan warkat khusus. 3. Warkat tersebut adalah cek dan bilyet giro." },
    { q: "Kredit bank adalah ...", options: ["penyediaan uang berdasarkan perjanjian pinjam-meminjam", "tabungan berjangka", "jual beli saham", "penukaran valuta asing"], answer: 0, solution: "1. Bank menyalurkan dana ke masyarakat yang membutuhkan. 2. Penyaluran disertai perjanjian pengembalian beserta bunga. 3. Penyediaan uang berdasarkan perjanjian pinjam-meminjam ini disebut kredit." },
    { q: "Prinsip 5C dalam pemberian kredit adalah ...", options: ["character, capacity, capital, collateral, condition", "cash, credit, check, control", "cepat, cair, pasti", "cermat, cepat, tepat"], answer: 0, solution: "1. Bank menilai calon debitur sebelum memberi kredit. 2. Penilaian mencakup watak, kemampuan, modal, jaminan, dan kondisi ekonomi. 3. Kelima prinsip ini disingkat 5C: character, capacity, capital, collateral, condition." },
    { q: "Agunan dalam istilah perbankan sama dengan ...", options: ["collateral (jaminan)", "character", "capacity", "condition"], answer: 0, solution: "1. Bank meminta jaminan atas kredit yang diberikan. 2. Jaminan (agunan) disita jika debitur gagal bayar. 3. Dalam prinsip 5C, agunan disebut collateral." },
    { q: "Bunga bank adalah ...", options: ["imbalan atas simpanan atau pinjaman", "pajak bank", "biaya administrasi", "denda keterlambatan"], answer: 0, solution: "1. Nasabah yang menabung mendapat tambahan, yang meminjam membayar tambahan. 2. Tambahan ini adalah harga dari uang. 3. Imbalan atas simpanan atau pinjaman ini disebut bunga bank." },
    { q: "Suku bunga acuan yang ditetapkan Bank Indonesia disebut ...", options: ["BI-Rate", "suku bunga deposito", "kurs tengah BI", "suku bunga pasar"], answer: 0, solution: "1. BI menetapkan suku bunga kebijakan sebagai sinyal moneter. 2. Suku bunga acuan ini menjadi patokan perbankan. 3. Suku bunga acuan BI disebut BI-Rate." },
    { q: "Jika Bank Indonesia menaikkan suku bunga acuan, maka ...", options: ["kredit menjadi lebih mahal sehingga jumlah kredit turun", "kredit menjadi murah", "tabungan berkurang", "inflasi naik"], answer: 0, solution: "1. Suku bunga acuan naik membuat biaya dana bank naik. 2. Bank meneruskan ke suku bunga kredit yang lebih tinggi. 3. Akibatnya kredit lebih mahal dan jumlah kredit turun." },
    { q: "Kliring dalam dunia perbankan adalah ...", options: ["penyelesaian utang-piutang antarbank", "pencetakan uang", "penukaran valuta asing", "audit bank"], answer: 0, solution: "1. Bank-bank saling memiliki tagihan lewat warkat nasabah. 2. Tagihan tersebut diselesaikan bersama secara berkala. 3. Penyelesaian utang-piutang antarbank ini disebut kliring." },
    { q: "Bank syariah beroperasi dengan prinsip ...", options: ["bagi hasil", "bunga tetap", "riba", "spekulasi"], answer: 0, solution: "1. Bank syariah tidak menggunakan sistem bunga. 2. Keuntungan dibagi antara bank dan nasabah sesuai kesepakatan. 3. Jadi bank syariah beroperasi dengan prinsip bagi hasil." },
    { q: "Akad mudharabah dalam bank syariah adalah akad ...", options: ["bagi hasil", "jual beli (murabahah)", "sewa-menyewa", "pinjam-meminjam"], answer: 0, solution: "1. Mudharabah adalah kerja sama pemilik modal dan pengelola. 2. Keuntungan usaha dibagi menurut nisbah yang disepakati. 3. Jadi akad mudharabah adalah akad bagi hasil." },
    { q: "Kegiatan usaha yang DILARANG dilakukan oleh BPR adalah ...", options: ["kegiatan valuta asing", "menerima tabungan", "memberi kredit kecil", "menerima deposito"], answer: 0, solution: "1. BPR adalah bank kecil yang fokus pada usaha mikro. 2. Undang-undang membatasi BPR agar tidak melakukan kegiatan bank umum. 3. Yang dilarang antara lain kegiatan valuta asing dan ikut kliring." },
    { q: "Perbedaan bank umum dan BPR adalah ...", options: ["BPR tidak boleh ikut kliring dan valuta asing", "BPR lebih besar", "bank umum milik daerah", "tidak ada bedanya"], answer: 0, solution: "1. Bank umum memiliki kegiatan usaha lengkap. 2. BPR dibatasi: tidak boleh giro, valas, dan kliring. 3. Jadi perbedaannya BPR tidak boleh ikut kliring dan valuta asing." },
    { q: "APBN ditetapkan setiap tahun dengan ...", options: ["undang-undang", "keputusan presiden", "peraturan BI", "peraturan daerah"], answer: 0, solution: "1. APBN adalah rencana keuangan negara yang mengikat. 2. Penetapannya memerlukan persetujuan DPR sebagai wakil rakyat. 3. APBN ditetapkan dengan undang-undang." },
    { q: "Tahun anggaran APBN Indonesia berjalan dari ...", options: ["1 Januari - 31 Desember", "1 April - 31 Maret", "1 Juli - 30 Juni", "1 Oktober - 30 September"], answer: 0, solution: "1. Indonesia memakai tahun anggaran kalender. 2. Dimulai awal Januari dan berakhir akhir Desember. 3. Jadi tahun anggaran APBN 1 Januari sampai 31 Desember." },
    { q: "Sumber penerimaan negara terbesar dalam APBN adalah ...", options: ["pajak", "hibah", "utang luar negeri", "denda"], answer: 0, solution: "1. Penerimaan negara terdiri atas pajak, PNBP, dan hibah. 2. Kontribusi terbesar berasal dari pungutan pajak. 3. Jadi sumber penerimaan terbesar adalah pajak." },
    { q: "Pajak yang dikenakan atas penyerahan barang kena pajak adalah ...", options: ["PPN", "PPh", "PBB", "bea materai"], answer: 0, solution: "1. Setiap penyerahan barang kena pajak di dalam negeri dipungut pajak. 2. Pajak atas nilai tambah barang tersebut disingkat PPN. 3. Jadi pajaknya adalah Pajak Pertambahan Nilai (PPN)." },
    { q: "PPh (Pajak Penghasilan) termasuk jenis pajak ...", options: ["langsung", "tidak langsung", "retribusi", "cukai"], answer: 0, solution: "1. Pajak langsung bebannya tidak dapat dialihkan ke pihak lain. 2. PPh dipungut langsung atas penghasilan wajib pajak. 3. Jadi PPh termasuk pajak langsung." },
    { q: "Fungsi pajak sebagai sumber penerimaan negara untuk belanja disebut fungsi ...", options: ["budgetair (anggaran)", "regulerend (mengatur)", "stabilisasi", "distribusi"], answer: 0, solution: "1. Salah satu fungsi pajak adalah mengisi kas negara. 2. Dana pajak dipakai membiayai belanja negara. 3. Fungsi pajak sebagai sumber anggaran ini disebut fungsi budgetair." },
    { q: "Fungsi pajak untuk mengatur kegiatan ekonomi masyarakat disebut fungsi ...", options: ["mengatur kegiatan ekonomi masyarakat", "mengisi kas negara", "menambah utang", "mencetak uang"], answer: 0, solution: "1. Pajak dapat dipakai mengendalikan konsumsi, misal cukai rokok. 2. Fungsi mengatur perilaku ekonomi ini berbeda dari fungsi anggaran. 3. Fungsi pajak untuk mengatur disebut fungsi regulerend." },
    { q: "Belanja negara dalam APBN terdiri atas ...", options: ["belanja pemerintah pusat dan transfer ke daerah", "gaji pegawai saja", "subsidi saja", "pembayaran bunga utang saja"], answer: 0, solution: "1. Belanja negara mencakup seluruh pengeluaran pemerintah. 2. Sebagian dibelanjakan kementerian/lembaga pusat, sebagian ditransfer ke daerah. 3. Jadi belanja negara terdiri atas belanja pemerintah pusat dan transfer ke daerah." },
    { q: "APBN mengalami surplus apabila ...", options: ["pendapatan lebih besar dari belanja", "belanja lebih besar dari pendapatan", "pendapatan sama dengan belanja", "utang lunas"], answer: 0, solution: "1. Surplus adalah kelebihan penerimaan. 2. Terjadi saat pendapatan negara melebihi belanjanya. 3. Jadi APBN surplus apabila pendapatan lebih besar dari belanja." },
    { q: "Perbedaan kebijakan fiskal dan kebijakan moneter terletak pada ...", options: ["pelakunya: pemerintah vs bank sentral", "tujuannya sama persis", "waktunya", "tidak ada bedanya"], answer: 0, solution: "1. Kebijakan fiskal mengatur pajak dan belanja negara. 2. Kebijakan moneter mengatur jumlah uang beredar. 3. Fiskal dijalankan pemerintah, moneter oleh bank sentral, jadi bedanya pada pelakunya." },
    { q: "Kebijakan fiskal ekspansif adalah kebijakan ...", options: ["menambah belanja negara atau menurunkan pajak", "mengurangi belanja dan menaikkan pajak", "menaikkan suku bunga", "menjual SBI"], answer: 0, solution: "1. Ekspansif berarti mendorong (mengekspansi) perekonomian. 2. Caranya menambah belanja negara atau menurunkan pajak agar daya beli naik. 3. Jadi kebijakan fiskal ekspansif adalah menambah belanja negara atau menurunkan pajak." },
    { q: "Kebijakan fiskal kontraktif adalah kebijakan ...", options: ["mengurangi belanja negara atau menaikkan pajak", "menambah belanja negara", "menurunkan pajak", "menambah utang"], answer: 0, solution: "1. Kontraktif berarti mengerem laju perekonomian. 2. Caranya mengurangi belanja negara atau menaikkan pajak. 3. Kebijakan ini dipakai antara lain untuk menekan inflasi." },
    { q: "Instrumen kebijakan fiskal adalah ...", options: ["pajak, belanja negara, dan utang", "suku bunga dan giro wajib minimum", "kurs dan devisa", "upah minimum"], answer: 0, solution: "1. Kebijakan fiskal dijalankan lewat penerimaan dan pengeluaran negara. 2. Penerimaan terutama pajak, pengeluaran berupa belanja negara, kekurangannya ditutup utang. 3. Jadi instrumennya pajak, belanja negara, dan utang." },
    { q: "Kekurangan APBN (defisit) ditutup melalui ...", options: ["pembiayaan (utang)", "mencetak uang seenaknya", "menaikkan gaji PNS", "hibah"], answer: 0, solution: "1. Defisit berarti belanja melebihi pendapatan. 2. Selisihnya harus ditutup dari sumber dana lain yang resmi. 3. Penutup defisit ini disebut pembiayaan, terutama melalui utang." },
    { q: "APBD ditetapkan oleh ...", options: ["pemerintah daerah bersama DPRD", "presiden dan DPR", "BI dan OJK", "menteri keuangan saja"], answer: 0, solution: "1. APBD adalah anggaran pendapatan dan belanja daerah. 2. Seperti APBN yang ditetapkan pemerintah bersama DPR, APBD ditetapkan daerah. 3. Jadi APBD ditetapkan pemerintah daerah bersama DPRD." },
    { q: "Dana desa bersumber dari ...", options: ["APBN", "APBD provinsi", "swadaya masyarakat", "utang desa"], answer: 0, solution: "1. Dana desa adalah alokasi untuk pembangunan desa. 2. Dana ini disalurkan pemerintah pusat ke rekening desa. 3. Jadi dana desa bersumber dari APBN." },
    { q: "Berikut ini yang termasuk pajak daerah adalah ...", options: ["PBB-P2 dan pajak kendaraan bermotor", "PPh", "PPN", "bea masuk"], answer: 0, solution: "1. Pajak pusat dipungut pemerintah pusat seperti PPh dan PPN. 2. Pajak daerah dipungut pemerintah daerah. 3. Contoh pajak daerah adalah PBB Perdesaan-Perkotaan dan pajak kendaraan bermotor." },
    { q: "Retribusi adalah ...", options: ["pungutan atas jasa yang diberikan pemerintah daerah", "pajak pusat", "sumbangan sukarela", "denda tilang"], answer: 0, solution: "1. Retribusi dipungut karena ada jasa langsung yang dinikmati. 2. Contohnya retribusi parkir dan pasar. 3. Jadi retribusi adalah pungutan atas jasa yang diberikan pemerintah daerah." },
    { q: "Subsidi BBM dalam APBN termasuk ...", options: ["belanja subsidi pemerintah pusat", "belanja daerah", "pembiayaan", "hibah"], answer: 0, solution: "1. Subsidi adalah bantuan harga dari pemerintah. 2. Subsidi BBM dianggarkan pemerintah pusat. 3. Jadi termasuk belanja subsidi pemerintah pusat." },
    { q: "Saat terjadi resesi, pemerintah sebaiknya ...", options: ["menambah belanja negara untuk proyek padat karya", "menaikkan pajak", "mengurangi belanja", "menaikkan suku bunga"], answer: 0, solution: "1. Resesi ditandai pengangguran tinggi dan daya beli lesu. 2. Pemerintah perlu menyuntik perekonomian lewat belanja. 3. Proyek padat karya menambah belanja sekaligus menyerap pengangguran." },
    { q: "Ekspor adalah kegiatan ...", options: ["menjual barang ke luar negeri", "membeli barang dari luar negeri", "menimbun barang", "menyelundupkan barang"], answer: 0, solution: "1. Perdagangan internasional terdiri atas ekspor dan impor. 2. Menjual (exit) barang ke luar negeri disebut ekspor. 3. Jadi ekspor adalah menjual barang ke luar negeri." },
    { q: "Impor adalah kegiatan ...", options: ["menjual barang ke luar negeri", "membeli barang dari luar negeri", "memproduksi sendiri", "mengekspor ulang"], answer: 1, solution: "1. Impor adalah lawan dari ekspor. 2. Membeli (in) barang dari luar negeri untuk kebutuhan dalam negeri. 3. Jadi impor adalah membeli barang dari luar negeri." },
    { q: "Neraca perdagangan mengalami defisit apabila ...", options: ["impor lebih besar dari ekspor", "ekspor lebih besar dari impor", "ekspor sama dengan impor", "tidak ada perdagangan"], answer: 0, solution: "1. Neraca perdagangan membandingkan nilai ekspor dan impor. 2. Defisit berarti tekor atau negatif. 3. Jadi defisit terjadi apabila impor lebih besar dari ekspor." },
    { q: "Devisa adalah ...", options: ["valuta asing sebagai alat pembayaran internasional", "utang luar negeri", "cadangan emas saja", "modal asing"], answer: 0, solution: "1. Transaksi internasional memerlukan alat pembayaran yang diterima dunia. 2. Mata uang asing yang berfungsi sebagai alat pembayaran internasional disebut devisa. 3. Jadi devisa adalah valuta asing sebagai alat pembayaran internasional." },
    { q: "Kurs adalah ...", options: ["harga mata uang asing dalam rupiah", "suku bunga bank", "harga emas", "indeks saham"], answer: 0, solution: "1. Untuk menukar dolar ke rupiah perlu diketahui nilainya. 2. Nilai tukar mata uang asing terhadap rupiah disebut kurs. 3. Jadi kurs adalah harga mata uang asing dalam rupiah." },
    { q: "Apresiasi rupiah berarti ...", options: ["rupiah menguat terhadap dolar AS", "rupiah melemah", "dolar menguat", "harga barang naik"], answer: 0, solution: "1. Apresiasi berarti kenaikan nilai. 2. Rupiah terapresiasi artinya nilai rupiah naik terhadap dolar. 3. Jadi apresiasi rupiah berarti rupiah menguat terhadap dolar AS." },
    { q: "Depresiasi rupiah berarti ...", options: ["rupiah melemah terhadap dolar AS", "rupiah menguat", "harga barang turun", "ekspor naik"], answer: 0, solution: "1. Depresiasi berarti penurunan nilai. 2. Rupiah terdepresiasi artinya butuh lebih banyak rupiah untuk satu dolar. 3. Jadi depresiasi rupiah berarti rupiah melemah terhadap dolar AS." },
    { q: "Jika rupiah terapresiasi terhadap dolar AS, artinya ...", options: ["satu dolar AS ditukar dengan rupiah yang lebih sedikit", "rupiah dicetak lebih banyak", "harga barang naik", "suku bunga turun"], answer: 0, solution: "1. Rupiah menguat berarti daya belinya terhadap dolar naik. 2. Satu dolar kini hanya setara rupiah lebih sedikit. 3. Jadi apresiasi berarti satu dolar AS ditukar dengan rupiah yang lebih sedikit." },
    { q: "Dampak depresiasi rupiah bagi eksportir Indonesia adalah ...", options: ["diuntungkan karena barangnya lebih murah bagi pembeli asing", "dirugikan", "bangkrut", "tidak berpengaruh"], answer: 0, solution: "1. Rupiah melemah membuat harga barang Indonesia murah dalam dolar. 2. Pembeli asing makin tertarik membeli. 3. Jadi eksportir diuntungkan karena barangnya lebih murah bagi pembeli asing." },
    { q: "Dampak depresiasi rupiah bagi importir Indonesia adalah ...", options: ["diuntungkan", "dirugikan karena barang impor lebih mahal", "tidak terpengaruh", "untung besar"], answer: 1, solution: "1. Rupiah melemah membuat satu dolar butuh rupiah lebih banyak. 2. Barang impor yang dibayar dengan dolar menjadi lebih mahal. 3. Jadi importir dirugikan karena barang impor lebih mahal." },
    { q: "Berikut ini kebijakan proteksi perdagangan, KECUALI ...", options: ["tarif bea masuk", "kuota impor", "subsidi ekspor", "perdagangan bebas"], answer: 3, solution: "1. Proteksi adalah perlindungan terhadap produk dalam negeri. 2. Caranya dengan tarif, kuota, subsidi, dan larangan impor. 3. Perdagangan bebas justru kebalikan dari proteksi." },
    { q: "Tarif (bea masuk) adalah ...", options: ["pajak atas barang impor", "pajak penghasilan", "subsidi", "kuota"], answer: 0, solution: "1. Barang impor yang masuk dikenakan pungutan di bea cukai. 2. Pungutan ini menambah harga barang impor agar kalah bersaing. 3. Pajak atas barang impor ini disebut tarif atau bea masuk." },
    { q: "Kuota impor adalah ...", options: ["pembatasan jumlah barang impor", "pajak atas barang impor", "larangan total impor", "subsidi impor"], answer: 0, solution: "1. Selain lewat pajak, impor dapat dibatasi jumlahnya. 2. Batas maksimal jumlah barang yang boleh diimpor ditetapkan pemerintah. 3. Pembatasan jumlah barang impor ini disebut kuota impor." },
    { q: "Tujuan utama kebijakan proteksi adalah ...", options: ["melindungi industri dalam negeri", "menambah impor", "menurunkan harga", "membuka pasar bebas"], answer: 0, solution: "1. Industri dalam negeri kalah bersaing dengan produk impor murah. 2. Pemerintah melindunginya agar dapat tumbuh. 3. Jadi tujuan proteksi adalah melindungi industri dalam negeri." },
    { q: "Organisasi perdagangan dunia disebut ...", options: ["WTO", "World Bank", "IMF", "ASEAN"], answer: 0, solution: "1. Perdagangan antarnegara memerlukan aturan main bersama. 2. Organisasi yang mengatur tata perdagangan dunia adalah WTO. 3. WTO adalah singkatan World Trade Organization." },
    { q: "Kerja sama perdagangan bebas antarnegara ASEAN disebut ...", options: ["AFTA", "Uni Eropa", "NAFTA", "APEC"], answer: 0, solution: "1. ASEAN membentuk kawasan perdagangan bebas. 2. Skema penurunan tarif antaranggota ASEAN ini bernama AFTA. 3. AFTA adalah ASEAN Free Trade Area." },
    { q: "MEA adalah singkatan dari ...", options: ["Masyarakat Ekonomi ASEAN", "Masyarakat Eropa Amerika", "Modal Ekonomi Asia", "Misi Ekonomi ASEAN"], answer: 0, solution: "1. ASEAN mengintegrasikan ekonominya lebih dalam. 2. Integrasi pasar tunggal dan basis produksi ASEAN ini disebut MEA. 3. MEA adalah Masyarakat Ekonomi ASEAN." },
    { q: "L/C adalah singkatan dari ...", options: ["Letter of Credit", "Letter of Cash", "Local Currency", "Loan Certificate"], answer: 0, solution: "1. Pembayaran ekspor-impor memerlukan jaminan bank. 2. Jaminan pembayaran dari bank ini disebut letter of credit. 3. Jadi L/C adalah Letter of Credit." },
    { q: "Teori keunggulan komparatif menyatakan negara sebaiknya berproduksi pada barang dengan ...", options: ["biaya peluang terendah", "memproduksi semua barang", "biaya tertinggi", "tanpa perdagangan"], answer: 0, solution: "1. Tidak semua negara unggul di semua barang. 2. David Ricardo menyarankan spesialisasi pada barang yang pengorbanannya paling kecil. 3. Jadi berproduksi pada barang dengan biaya peluang terendah (keunggulan komparatif)." },
    { q: "Teori keunggulan absolut dikemukakan oleh ...", options: ["Adam Smith", "David Ricardo", "J.S. Mill", "Heckscher-Ohlin"], answer: 0, solution: "1. Keunggulan absolut berarti mampu berproduksi lebih efisien dari negara lain. 2. Teori ini menjadi dasar awal perdagangan internasional. 3. Teori keunggulan absolut dikemukakan oleh Adam Smith." },
    { q: "Dampak positif perdagangan internasional bagi Indonesia adalah ...", options: ["menambah devisa dan memperluas pasar", "ketergantungan impor", "mematikan industri lokal", "defisit neraca"], answer: 0, solution: "1. Ekspor menghasilkan devisa bagi negara. 2. Pasar yang lebih luas meningkatkan produksi dan lapangan kerja. 3. Jadi dampak positifnya menambah devisa dan memperluas pasar." },
    { q: "Bank menjual dolar AS kepada nasabah dengan menggunakan ...", options: ["kurs jual yang lebih tinggi dari kurs beli", "kurs beli", "kurs tengah", "kurs bebas"], answer: 0, solution: "1. Bank mengambil untung dari selisih kurs. 2. Saat menjual valas, bank memakai kurs yang lebih tinggi. 3. Jadi bank menjual dolar dengan kurs jual yang lebih tinggi dari kurs beli." },
    { q: "Seorang turis menukar USD 100 dengan kurs beli Rp15.800 per dolar. Rupiah yang diterimanya sebesar ...", options: ["Rp1.580.000", "Rp1.680.000", "Rp1.480.000", "Rp15.800.000"], answer: 0, solution: "1. Turis menjual dolar ke bank sehingga dipakai kurs beli. 2. Hitung: 100 x Rp15.800 = Rp1.580.000. 3. Jadi rupiah yang diterima sebesar Rp1.580.000." },
    { q: "Kurs rupiah terhadap dolar AS berubah dari Rp15.000 menjadi Rp16.000 per dolar. Hal ini berarti rupiah ...", options: ["terdepresiasi", "terapresiasi", "menguat", "tidak berubah"], answer: 0, solution: "1. Semula satu dolar setara Rp15.000, kini Rp16.000. 2. Dibutuhkan rupiah lebih banyak untuk satu dolar, artinya nilai rupiah turun. 3. Penurunan nilai rupiah ini disebut depresiasi." },
    { q: "Akuntansi adalah ...", options: ["seni pencatatan, penggolongan, dan peringkasan transaksi", "ilmu menabung", "teknik berdagang", "cara menghitung pajak"], answer: 0, solution: "1. Perusahaan mencatat setiap transaksi keuangannya. 2. Catatan digolongkan ke akun-akun lalu diringkas jadi laporan. 3. Seni pencatatan, penggolongan, dan peringkasan transaksi ini disebut akuntansi." },
    { q: "Diketahui modal Rp25.000.000 dan kewajiban Rp15.000.000. Total aset perusahaan adalah ...", options: ["Rp40.000.000", "Rp10.000.000", "Rp25.000.000", "Rp15.000.000"], answer: 0, solution: "1. Persamaan dasar akuntansi: Aset = Kewajiban + Modal. 2. Masukkan angka: 25.000.000 + 15.000.000 = 40.000.000. 3. Jadi total aset perusahaan adalah Rp40.000.000." },
    { q: "Kelompok akun yang termasuk akun nominal adalah ...", options: ["pendapatan dan beban", "aset dan kewajiban", "kas dan modal", "piutang dan utang"], answer: 0, solution: "1. Akun nominal adalah akun sementara yang ditutup tiap periode. 2. Akun ini mengukur hasil usaha selama satu periode. 3. Akun nominal terdiri atas pendapatan dan beban." },
    { q: "Kelompok akun yang termasuk akun riil adalah ...", options: ["aset, kewajiban, dan modal", "pendapatan dan beban", "prive dan modal", "kas dan beban"], answer: 0, solution: "1. Akun riil adalah akun permanen yang saldonya berlanjut. 2. Akun ini menggambarkan posisi keuangan perusahaan. 3. Akun riil terdiri atas aset, kewajiban, dan modal." },
    { q: "Dalam akuntansi, sisi debit terletak di sebelah ...", options: ["kiri", "kanan", "atas", "bawah"], answer: 0, solution: "1. Setiap akun memiliki dua sisi pencatatan. 2. Sisi kiri disebut debit, sisi kanan disebut kredit. 3. Jadi debit terletak di sebelah kiri." },
    { q: "Akun aset yang bertambah dicatat di sisi ...", options: ["debit", "kredit", "tetap", "nol"], answer: 0, solution: "1. Aset adalah harta perusahaan di sisi kiri persamaan akuntansi. 2. Penambahan akun di sisi kiri dicatat di debit. 3. Jadi aset yang bertambah dicatat di debit." },
    { q: "Akun kewajiban yang bertambah dicatat di sisi ...", options: ["debit", "kredit", "tetap", "nol"], answer: 1, solution: "1. Kewajiban ada di sisi kanan persamaan akuntansi. 2. Penambahan akun di sisi kanan dicatat di kredit. 3. Jadi kewajiban yang bertambah dicatat di kredit." },
    { q: "Akun modal yang bertambah dicatat di sisi ...", options: ["debit", "kredit", "tetap", "nol"], answer: 1, solution: "1. Modal juga berada di sisi kanan persamaan akuntansi. 2. Penambahan akun di sisi kanan dicatat di kredit. 3. Jadi modal yang bertambah dicatat di kredit." },
    { q: "Akun pendapatan yang bertambah dicatat di sisi ...", options: ["debit", "kredit", "tetap", "nol"], answer: 1, solution: "1. Pendapatan menambah modal pemilik. 2. Modal yang bertambah dicatat di kredit. 3. Jadi pendapatan yang bertambah dicatat di kredit." },
    { q: "Akun beban yang bertambah dicatat di sisi ...", options: ["debit", "kredit", "tetap", "nol"], answer: 0, solution: "1. Beban mengurangi modal pemilik. 2. Pengurang modal dicatat berlawanan dengan modal, yaitu debit. 3. Jadi beban yang bertambah dicatat di debit." },
    { q: "Akun prive yang bertambah dicatat di sisi ...", options: ["debit", "kredit", "tetap", "nol"], answer: 0, solution: "1. Prive adalah pengambilan modal oleh pemilik. 2. Prive mengurangi modal sehingga dicatat berlawanan dengan modal. 3. Jadi prive yang bertambah dicatat di debit." },
    { q: "Dibeli peralatan Rp5.000.000 secara tunai. Jurnal yang benar adalah ...", options: ["Peralatan (D) Rp5.000.000; Kas (K) Rp5.000.000", "Kas (D) Rp5.000.000; Peralatan (K) Rp5.000.000", "Peralatan (D) Rp5.000.000; Utang Usaha (K) Rp5.000.000", "Beban (D) Rp5.000.000; Kas (K) Rp5.000.000"], answer: 0, solution: "1. Peralatan bertambah (aset bertambah dicatat di debit). 2. Kas berkurang karena dibayar tunai (aset berkurang dicatat di kredit). 3. Jadi jurnalnya: Peralatan (D) Rp5.000.000; Kas (K) Rp5.000.000." },
    { q: "Diterima pendapatan jasa Rp2.000.000 secara tunai. Jurnal yang benar adalah ...", options: ["Kas (D) Rp2.000.000; Pendapatan Jasa (K) Rp2.000.000", "Pendapatan Jasa (D) Rp2.000.000; Kas (K) Rp2.000.000", "Kas (D) Rp2.000.000; Modal (K) Rp2.000.000", "Piutang Usaha (D) Rp2.000.000; Kas (K) Rp2.000.000"], answer: 0, solution: "1. Kas bertambah karena diterima tunai (aset bertambah di debit). 2. Pendapatan jasa bertambah (pendapatan bertambah di kredit). 3. Jadi jurnalnya: Kas (D) Rp2.000.000; Pendapatan Jasa (K) Rp2.000.000." },
    { q: "Dibayar beban listrik Rp750.000 secara tunai. Jurnal yang benar adalah ...", options: ["Beban Listrik (D) Rp750.000; Kas (K) Rp750.000", "Kas (D) Rp750.000; Beban Listrik (K) Rp750.000", "Utang Usaha (D) Rp750.000; Kas (K) Rp750.000", "Beban Listrik (D) Rp750.000; Modal (K) Rp750.000"], answer: 0, solution: "1. Beban listrik bertambah (beban bertambah di debit). 2. Kas berkurang karena dibayar tunai (aset berkurang di kredit). 3. Jadi jurnalnya: Beban Listrik (D) Rp750.000; Kas (K) Rp750.000." },
    { q: "Pemilik menyetor modal Rp10.000.000 secara tunai. Jurnal yang benar adalah ...", options: ["Kas (D) Rp10.000.000; Modal (K) Rp10.000.000", "Modal (D) Rp10.000.000; Kas (K) Rp10.000.000", "Kas (D) Rp10.000.000; Prive (K) Rp10.000.000", "Utang Usaha (D) Rp10.000.000; Kas (K) Rp10.000.000"], answer: 0, solution: "1. Kas bertambah karena ada setoran tunai (aset bertambah di debit). 2. Modal bertambah karena setoran pemilik (modal bertambah di kredit). 3. Jadi jurnalnya: Kas (D) Rp10.000.000; Modal (K) Rp10.000.000." },
    { q: "Dibeli perlengkapan Rp1.500.000 secara kredit. Jurnal yang benar adalah ...", options: ["Perlengkapan (D) Rp1.500.000; Utang Usaha (K) Rp1.500.000", "Kas (D) Rp1.500.000; Perlengkapan (K) Rp1.500.000", "Utang Usaha (D) Rp1.500.000; Kas (K) Rp1.500.000", "Beban Perlengkapan (D) Rp1.500.000; Utang Usaha (K) Rp1.500.000"], answer: 0, solution: "1. Perlengkapan bertambah (aset bertambah di debit). 2. Pembelian kredit menimbulkan utang usaha (kewajiban bertambah di kredit). 3. Jadi jurnalnya: Perlengkapan (D) Rp1.500.000; Utang Usaha (K) Rp1.500.000." },
    { q: "Diterima pelunasan piutang Rp3.000.000 secara tunai. Jurnal yang benar adalah ...", options: ["Kas (D) Rp3.000.000; Piutang Usaha (K) Rp3.000.000", "Piutang Usaha (D) Rp3.000.000; Kas (K) Rp3.000.000", "Kas (D) Rp3.000.000; Pendapatan Jasa (K) Rp3.000.000", "Utang Usaha (D) Rp3.000.000; Kas (K) Rp3.000.000"], answer: 0, solution: "1. Kas bertambah karena diterima tunai (aset bertambah di debit). 2. Piutang berkurang karena dilunasi (aset berkurang di kredit). 3. Jadi jurnalnya: Kas (D) Rp3.000.000; Piutang Usaha (K) Rp3.000.000." },
    { q: "Dibayar utang usaha Rp2.500.000 secara tunai. Jurnal yang benar adalah ...", options: ["Utang Usaha (D) Rp2.500.000; Kas (K) Rp2.500.000", "Kas (D) Rp2.500.000; Utang Usaha (K) Rp2.500.000", "Beban (D) Rp2.500.000; Kas (K) Rp2.500.000", "Utang Usaha (D) Rp2.500.000; Modal (K) Rp2.500.000"], answer: 0, solution: "1. Utang usaha berkurang karena dibayar (kewajiban berkurang di debit). 2. Kas berkurang karena dibayar tunai (aset berkurang di kredit). 3. Jadi jurnalnya: Utang Usaha (D) Rp2.500.000; Kas (K) Rp2.500.000." },
    { q: "Pendapatan jasa Rp20.000.000, beban gaji Rp6.000.000, dan beban sewa Rp3.000.000. Laba bersihnya adalah ...", options: ["Rp11.000.000", "Rp14.000.000", "Rp9.000.000", "Rp20.000.000"], answer: 0, solution: "1. Total beban = 6.000.000 + 3.000.000 = 9.000.000. 2. Laba bersih = pendapatan - total beban = 20.000.000 - 9.000.000. 3. Jadi laba bersihnya Rp11.000.000." },
    { q: "Modal awal Rp50.000.000, selama setahun menderita rugi Rp5.000.000 dan prive Rp3.000.000. Modal akhirnya adalah ...", options: ["Rp42.000.000", "Rp48.000.000", "Rp52.000.000", "Rp58.000.000"], answer: 0, solution: "1. Rumus: Modal akhir = Modal awal - Rugi - Prive. 2. Hitung: 50.000.000 - 5.000.000 - 3.000.000 = 42.000.000. 3. Jadi modal akhirnya Rp42.000.000." },
    { q: "Neraca saldo adalah ...", options: ["daftar saldo akun-akun buku besar", "catatan transaksi harian", "laporan laba rugi", "bukti transaksi"], answer: 0, solution: "1. Setelah transaksi dibukukan ke buku besar, tiap akun punya saldo. 2. Saldo-saldo tersebut disusun dalam satu daftar untuk dicek keseimbangannya. 3. Daftar saldo akun-akun buku besar ini disebut neraca saldo." },
    { q: "Jurnal umum mencatat transaksi secara ...", options: ["kronologis sesuai tanggal transaksi", "acak", "berdasarkan jumlahnya", "berdasarkan abjad"], answer: 0, solution: "1. Jurnal adalah catatan pertama setiap transaksi. 2. Pencatatan dilakukan berurutan sesuai waktu terjadinya. 3. Jadi jurnal umum mencatat transaksi secara kronologis sesuai tanggal." },
    { q: "Buku besar adalah ...", options: ["kumpulan akun-akun", "buku catatan harian", "laporan keuangan", "kumpulan kwitansi"], answer: 0, solution: "1. Transaksi dari jurnal perlu dikelompokkan per jenis akun. 2. Pengelompokan ini menghasilkan buku berisi seluruh akun perusahaan. 3. Kumpulan akun-akun ini disebut buku besar." },
    { q: "Laporan keuangan perusahaan jasa terdiri atas ...", options: ["laporan laba rugi, laporan perubahan modal, dan neraca", "jurnal umum dan buku besar", "nota dan kwitansi", "anggaran dan realisasi"], answer: 0, solution: "1. Laporan keuangan menyajikan hasil usaha dan posisi keuangan. 2. Hasil usaha disajikan di laba rugi, perubahan modal di laporan perubahan modal, posisi di neraca. 3. Jadi terdiri atas laporan laba rugi, laporan perubahan modal, dan neraca." },
    { q: "Laporan perubahan modal menyajikan ...", options: ["modal awal, laba/rugi, prive, dan modal akhir", "aset dan kewajiban", "pendapatan saja", "kas masuk dan kas keluar"], answer: 0, solution: "1. Modal berubah karena laba/rugi dan prive selama periode. 2. Laporan ini merunut perubahan dari awal hingga akhir periode. 3. Jadi menyajikan modal awal, laba/rugi, prive, dan modal akhir." },
    { q: "Akun yang ditutup pada akhir periode akuntansi adalah akun ...", options: ["nominal (pendapatan, beban, dan prive)", "aset", "kewajiban", "modal"], answer: 0, solution: "1. Akun nominal hanya mengukur hasil satu periode. 2. Agar periode baru mulai dari nol, akun ini ditutup lewat jurnal penutup. 3. Jadi yang ditutup adalah akun nominal: pendapatan, beban, dan prive." },
    { q: "Diterima pendapatan jasa Rp5.000.000, kas yang diterima Rp3.000.000 dan sisanya piutang. Jurnal yang benar adalah ...", options: ["Kas (D) Rp3.000.000; Piutang Usaha (D) Rp2.000.000; Pendapatan Jasa (K) Rp5.000.000", "Kas (D) Rp5.000.000; Pendapatan Jasa (K) Rp5.000.000", "Piutang Usaha (D) Rp5.000.000; Kas (K) Rp5.000.000", "Pendapatan Jasa (D) Rp5.000.000; Kas (K) Rp5.000.000"], answer: 0, solution: "1. Kas bertambah 3.000.000 (debit) dan piutang bertambah 2.000.000 (debit). 2. Pendapatan jasa bertambah 5.000.000 (kredit). 3. Jadi jurnalnya: Kas (D) 3.000.000; Piutang Usaha (D) 2.000.000; Pendapatan Jasa (K) 5.000.000." },
    { q: "Transaksi yang menambah aset sekaligus menambah kewajiban adalah ...", options: ["membeli peralatan secara kredit", "membayar utang usaha", "menerima pelunasan piutang", "mengambil prive"], answer: 0, solution: "1. Membeli peralatan menambah aset peralatan. 2. Karena secara kredit, muncul kewajiban berupa utang usaha. 3. Jadi transaksi ini menambah aset sekaligus menambah kewajiban." },
    { q: "Teknologi produksi yang semakin membaik menyebabkan penawaran barang ...", options: ["berkurang", "bertambah (kurva bergeser ke kanan)", "tetap", "menjadi nol"], answer: 1, solution: "1. Teknologi yang lebih baik membuat proses produksi lebih efisien. 2. Biaya per unit turun sehingga produsen mampu menawarkan lebih banyak pada setiap tingkat harga. 3. Jadi penawaran bertambah dan kurva penawaran bergeser ke kanan." }
  ]
};
